-- wger exercises, part 1 (generated by scripts/import_wger.py; CC licences, author per row).
-- Existing exercises win: a clashing name or id is skipped.
insert into public.exercises (id, name, main_muscles, form_instructions, equipment, source, license, author, source_url)
values
  ('c463f618-2777-4836-9c57-92a46d87cf1b', '1 Leg Box Squat', 'Hamstrings, Quads', 'This exercise requires a sturdy box or a chair. Simple stand ~6 inches in front of it and balance yourself on one leg. From here, begin squatting down in a smooth controlled motion while keeping your other leg straight out in front of you for balance. Slowly sit down on the box, pause for a 1 count and push back up with the working leg, while never letting your other leg touch the ground.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'jesusd', 'https://wger.de/en/exercise/1948/view/'),
  ('a8a4ea81-9531-48e1-b6dc-f7621c7b9283', '1-Arm Half-Kneeling Lat Pulldown', 'Lats', 'Attach a D-Handle to a high pully. And use your lat muscles to pull the weight single handedly.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1470/view/'),
  ('d561c00c-436d-47d9-b647-222e7b637abd', '1/2 Kneeling Thoracic Rotation', null, '- Begin in a half kneeling position with the
leg away from the wall stabilized against the wall
with a ball.
- With both hands directly in front of
you, rotate one arm open attempting to reach
the wall behind you.
- Exhale as you rotate, inhale
as you return to neutral and repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'amwang4', 'https://wger.de/en/exercise/1966/view/'),
  ('1b020b3a-3732-4c7e-92fd-a0cec90ed69b', '2 Handed Kettlebell Swing', 'Hamstrings, Glutes', '- Stand with your feet slightly wider than shoulder-width, the kettlebell on the floor about 20-30 cm in front of your toes.
- Hinge at the hips with a slight bend in the knees and a flat back, and grip the handle with both hands.
- Hike the kettlebell back between your legs, then drive your hips forward explosively so that it swings forward and up to chest or shoulder height (Russian style, not overhead). Your arms stay straight and relaxed, the power comes from the hips.
- Let the kettlebell swing back down, hinge again as it passes between your legs and go straight into the next rep.', 'Kettlebell', 'wger', 'CC-BY-SA 4', 'deusinvictus', 'https://wger.de/en/exercise/9/view/'),
  ('7870ad8d-a0c1-4e3a-a4fe-a237908eba9b', '3008 Abdominal Crunch', 'Abs', 'This is especially for the gym80 device 3008 Abdominal Crunch.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1924/view/'),
  ('7c2a70bc-ed97-440c-afd6-ed27daf63f25', '3D lunge warmup', null, 'As a warmup, use light dumbbells, one in each hand. Lunge in alternating directions, forward, sideways, backwards and 45 degree angles.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1115/view/'),
  ('18d277a0-7222-46e7-b2bf-47c8ed169c30', '4-count burpees', null, 'Starting position:
Stand straight, feet hip-width apart.
Steps:
- Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight.
- Keeping your hands on the floor, jump your legs backward into high plank position.
- Jump your feet forward to return to the squat position.
- Repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/997/view/'),
  ('1f2ba913-3b2e-4621-a70b-b7f0ce649032', '45° lateral raises', null, 'Dumbbell raise at an angle halfway between a front raise and a lateral raise.', 'Dumbbell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1754/view/'),
  ('7bd11f85-69a1-42ea-9924-7df7ba6d4f10', '90/90 Breathing', null, 'Controlled breathing drill performed in a 90/90 position to encourage rib, abdominal, and pelvic coordination.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/2564/view/'),
  ('a825d0f7-de61-4ca3-a2b2-0f8b00303464', '90/90 Hip Switches', 'Glutes', 'Sit on the floor with one leg bent at 90 degrees in front of you and the other leg bent at 90 degrees out to the side, so that the rear shin is parallel to the front shin. Keep your torso upright and, if possible, your hands off the floor.
Rotate both knees over to the other side so that the legs swap positions and you arrive in the same 90/90 position facing the opposite way. Move slowly and under control, keeping the feet in contact with the floor, and alternate sides for the desired number of repetitions.
Mobility drill for internal and external rotation of the hips.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/2613/view/'),
  ('203a6fee-7436-4313-858f-c1e364136793', 'Ab wheel', 'Abs', '- Starting Position: Kneel on the floor with the ab wheel in front of you.
- Grip the Wheel: Hold the handles firmly.
- Roll Out: Slowly roll the wheel forward, extending your body while keeping your core tight.
- Return: Pull the wheel back towards your knees, maintaining tension in your core.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'lhegedus', 'https://wger.de/en/exercise/1573/view/'),
  ('2ac901e6-f0c2-416f-998f-e01e00fe0aa1', 'Abdominal Crunch', 'Abs', 'The Abdominal Crunch is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor.', 'Gym mat', 'wger', 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1933/view/'),
  ('793b0e5f-8dea-48a6-84c8-9123b59c2721', 'Abdominal Draw-In', 'Abs', 'Lie
on your back with knees bent. Gently pull your belly button toward your
spine without moving your hips or holding your breath.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1828/view/'),
  ('03db11cc-8079-463c-9399-6f346b100ce6', 'Abdominal Stabilization', 'Abs', null, 'Gym mat', 'wger', 'CC-BY-SA 3', 'andikeller', 'https://wger.de/en/exercise/56/view/'),
  ('d015a276-02ad-4c28-9d36-aedfbb431f53', 'Abduction while standing', null, 'Training a stable stance, predominantly on one leg, is crucial for both sides. On the one hand, it prevents discomfort and, on the other, it establishes a stable foundation. The practitioner assumes the usual standing position and, with a stable upper body, attempts to repeatedly lift the unloaded leg, bend it at the hip and knee, and then lower it again. The movement is also repeated on the other side. The exercise trains the stability of the hip-surrounding muscles.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'tregga', 'https://wger.de/en/exercise/1096/view/'),
  ('04931134-da5d-4d87-8e62-bdcc0d970b0c', 'Active Hang', 'Lats, Trapezius', 'A static hold from a pull-up bar with straight elbows and actively depressed, stabilized shoulders. Grip a secure bar and let your body hang under control. Keep your elbows straight and gently draw your shoulders down, away from your ears. Maintain this active shoulder position without pulling up, swinging, or repeatedly moving the shoulder blades. Hold for up to 30 seconds. Stop earlier if your grip opens, shoulder control deteriorates, or pain occurs. Record actual seconds, grip, and any assistance used. This is distinct from a relaxed passive dead hang or a moving scapular pull-up.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'nalhilal', 'https://wger.de/en/exercise/2690/view/'),
  ('4e396da7-b25e-42de-a507-fe1aeb4f3f77', 'Adductor Rock Backs', null, 'Start on all fours with your hands under your shoulders and your knees under your hips. Extend one leg straight out to the side with the foot flat on the floor and the toes pointing forward.
Keep your back flat and slowly push your hips back towards the heel of the kneeling leg until you feel a stretch along the inside of the extended leg. Pause briefly, then return to the starting position. Complete all repetitions on one side before switching legs.
Mobility exercise for the adductors and the hips.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/2614/view/'),
  ('5831bcbb-28a7-4bd5-930d-a740acccf747', 'Alternate back lunges', 'Glutes, Quads', 'The posterior muscles of the buttocks, hamstrings, soleus and gastrocnemius are trained more', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1102/view/'),
  ('6c34000f-5d0b-43a9-b16e-00fd00c6db78', 'Alternate Walking', 'Calves, Quads', '1m30s of walking (~4.5 km/h) to 30 s of jog (7 km/h) and repeat', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Mamo2604', 'https://wger.de/en/exercise/2670/view/'),
  ('a136959c-b0c8-49d3-99b9-0a5f41abf00e', 'Alternating bicep curls', 'Biceps', 'Starting position:
Start standing up with dumbbells in each hand, your back straight and feet hip-width apart. Your arms should be relaxed, pointing down. Your knees should be slightly bent, your abs contracted, and your shoulders down.
Steps:
- Bend one arm at the elbow, bringing the dumbbell up to your shoulder. Your upper arm should remain motionless during this movement.
- Bring the dumbbell back down until your arm is in its original relaxed position.
- Repeat, switching arms.', 'Dumbbell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1012/view/'),
  ('94238bef-15ee-42b6-8035-79854b3c6e65', 'Alternating Biceps Curls With Dumbbell', 'Biceps', 'Hold two dumbbells, the arms are streched, the hands are on your
side, the palms face inwards. Bend one arm at a time and bring the weight with a
fast movement up. At the same time, rotate your arms by 90 degrees at
the very beginning of the movement. At the highest point, rotate a
little the weights further outwards. Without a pause, bring the arm back down, slowly, and do the same with the other arm.
Don''t allow your body to swing during the exercise, all work is done
by the biceps, which are the only mucles that should move (pay attention
to the elbows).', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1192/view/'),
  ('eb9476ac-2c00-4f49-a40f-f81682161a75', 'Alternating dumbbell hammer curl', 'Biceps', 'Stand with your knees slightly bent and your back straight. Hold a dumbbell in each hand, using a neutral grip at your sides.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Mariano_O', 'https://wger.de/en/exercise/1567/view/'),
  ('45251627-5f89-4858-bf0c-8884a21cbb1f', 'Alternating High Cable Row', 'Lats', '- Start
by putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab
the cable pulley handle in your left hand at about head height with your elbow slightly bent. Step back with your left foot.
- Pull
your elbow joint in toward the torso twisting slightly and perform a
single-arm row. Engage the lats as you twist.
- Return
to the starting position with cable pulley and left foot and grab the cable pulley handle in the right
hand. Repeat this motion on the opposite side with your right foot stepped back.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1486/view/'),
  ('81015468-545f-4170-9b46-701afe77848e', 'Alternative DB Gorilla rows', 'Lats', 'Slightly bent down and knees to mimic a gorilla position and pull/row up the DBs to the chest. DB stay straight (thumbs pointing up)', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1501/view/'),
  ('fa5252d3-973c-4b35-9324-a02460545283', 'ankle dorsiflexion rocks', 'Calves, Soleus', 'Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1804/view/'),
  ('979e3433-4db8-4f37-a5e0-f43c86756690', 'Ankle Roll', null, 'Sit on the floor and lift one foot off the ground, for example by resting that leg on the other knee.
Slowly draw circles with your foot, moving only at the ankle. Do several circles in both directions, then switch feet.', null, 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1864/view/'),
  ('7dd7a735-c1fe-4ca0-a6e8-e825d897b065', 'Arabesque', 'Hamstrings, Glutes', 'Take all your weight onto one leg and you''re going to maintain that position, keeping your hips and pelvis level the whole time. With your back in a neutral position you want to tilt yourself forward kicking your leg back up and then slowly with your glutes bring yourself back up to neutral.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cleen', 'https://wger.de/en/exercise/1141/view/'),
  ('f4291da4-09c2-4605-a90c-c926c6a92515', 'Arch Hang', null, 'https://www.youtube.com/watch?v=C995b3KLXS4&t=7s
- Elbows should stay straight
- Hold it for time/reps
- Start at an active hang: https://www.youtube.com/watch?v=HoE-C85ZlCE
- Progress towards a 90 degree in your shoulder', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'wintercyan', 'https://wger.de/en/exercise/2533/view/'),
  ('56808c52-050e-4c24-9f27-2657f0462499', 'Archer Pull Up', 'Lats', 'An archer pull-up is an advanced bodyweight exercise that strengthens your back and biceps, serving as a progression towards a one-arm pull-up. It gets its name from the "bow-drawing" position your body takes at the top.Here''s how to do it:
- Grip: Grasp a pull-up bar with a wider-than-shoulder-width overhand grip.
- Starting Position: Hang with arms fully extended, engaging your core and keeping your shoulder blades pulled down.
- The Pull: Pull your body up towards one hand, similar to a regular pull-up. At the same time, extend the other arm out to the side, keeping it as straight as possible. Your chin should come towards the hand that is pulling.
- Hold & Lower: Briefly hold the top position where one arm is bent and pulling, and the other is extended. Slowly lower yourself back to the starting position with control.
- Alternate: Repeat the movement, pulling up towards the opposite hand.The key to this exercise is to keep the assisting arm as straight as possible to maximise the load on the working arm. This makes it a challenging but effective exercise for unilateral pulling strength.', null, 'wger', 'CC-BY-SA 4', 'Antsy6277', 'https://wger.de/en/exercise/1545/view/'),
  ('b48cd640-dd9f-4557-a4db-8cd33d5655a6', 'Arm and neck stretch', 'Shoulders, Trapezius, Triceps', 'Relieves tension in the upper body, especially useful for people with office jobs or prolonged postures.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1590/view/'),
  ('e62d52fa-32f9-4747-9005-f88f05dc8334', 'Arm Raises (T/Y/I)', 'Shoulders, Lats, Serratus anterior, Trapezius', 'Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back:
- T Raise: Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape.
- Y Raise: Lift your arms upward at about a 45° angle from your body to form a “Y” shape.
- I Raise: Raise your arms straight overhead, close together, forming an “I” shape.
Maintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'WiNNiE', 'https://wger.de/en/exercise/1606/view/'),
  ('f24cb758-9c0d-42d4-ad9e-6025c527dd13', 'Arnold Shoulder Press', 'Shoulders', 'Sit on a bench with your back supported. Hold a pair of dumbbells in front of your shoulders, palms facing you and elbows in front of your body.
Press the dumbbells overhead while rotating your hands, so that your palms face forward at the top. Stop just before your elbows lock out.
Reverse the movement under control: lower the dumbbells and turn your palms back towards you until you are in the starting position again.
As shown here: https://www.youtube.com/watch?v=vj2w851ZHRM', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'trzr23', 'https://wger.de/en/exercise/20/view/'),
  ('e4bbd8d8-20e1-4174-b785-2590d2a1a7ad', 'Assisted chin-ups', 'Biceps, Lats', 'Chin-ups with machine assistance (counterweights)', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1737/view/'),
  ('8bc4c616-e76b-4291-9074-186ecbbb3cfd', 'Assisted Pull-Up', 'Lats, Trapezius', 'The Assisted Pull-Up is a compound vertical pulling exercise performed on a machine with a counterweight platform or by using resistance bands. It mimics the mechanics of a standard pull-up but reduces the total weight you have to lift, making it an excellent tool for building functional strength and perfecting your technique.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1929/view/'),
  ('4037fc14-d7a9-4901-8341-6538e415adc4', 'Australian pull-ups', 'Shoulders, Biceps, Lats', '- Lie down under a high bar or suspension bar, positioned at an appropriate height.
- Position yourself on your back under the bar, gripping the bar with a supinated grip (palms facing you).
- Adjust your position so that your body is aligned straight from head to toe. Arms should be fully extended, shoulders stabilized, and legs aligned with the rest of the body.
- Bend your elbows and pull your chest towards the bar, contracting your back muscles. Imagine you''re trying to bring your shoulder blades together.
- Hold the contraction at the top of the movement for a moment to maximize muscle activation.
- Slowly return to the starting position, extending your elbows.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'PaukOne', 'https://wger.de/en/exercise/1219/view/'),
  ('f2733700-aa5d-4df7-bc52-1876ab4fb479', 'Axe Hold', null, 'Hold a dumbbell in each hand and raise your straight arms out to the sides to shoulder height. Hold this position for as long as you can.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'GrosseHund', 'https://wger.de/en/exercise/31/view/'),
  ('17593b54-1e4e-49d7-8f9f-3a706823a4c5', 'Back bridge', null, 'Lie on the floor with your back resting on the floor and your legs bent, feet flat on the floor, leaving about 20 cm between your feet and your buttocks. Your hands remain flat on the floor, pressed against your ears, with your fingers pointing toward your toes. Your elbows are bent and pointing toward the ceiling. This is the starting position. Now push your hips as high as you can, raising your body off the floor, and continue pushing through your hands, extending your elbows and knees, until your back is fully arched (lumbar bridge). Your head also comes off the floor and should be level with your elbows, looking back. This is the final position. The descent should be slow and controlled. Your spine should be in a convex curve. It''s not good to lift your back off the floor; it should remain straight. It should be well rounded. You''ll also notice a feeling of increased oxygenation in your back. After lifting off the floor, your hips should be very high, even above the level of your head. Your arms and legs should remain straight. It seems easy, but it requires a good level of flexibility. Breathing should be deep. This posture stretches the rib cage and puts pressure on the diaphragm. If the posture is performed correctly, breathing will be perfect. Never hold your breath during the exercise.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1263/view/'),
  ('8e1cda15-542b-4714-8cc5-c1fe5089ee27', 'Back Lever', null, 'Hanging from a pull-up bar facing downwards with your arms extended', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1742/view/'),
  ('b646e62d-c616-4460-b4d1-23cc6a6ddb51', 'Back neck stretch', null, 'Starting position:
Sit upright on a chair or a firm pillow.
Steps:
- Breathe out and tilt your head forward, chin to chest, putting hands behind your head.
- Use your hands to pull your head down lightly and press against your hands with your head to balance out the force.
- Hold for a bit.
- Relax your arms and head, opening up a bit with your shoulders.
- Keep repeating this from step 2 onward.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1010/view/'),
  ('69b3da17-11cc-41fe-bbc1-ee6c45ced41c', 'Backward arm circles', null, 'Starting position:
Stand tall with your back straight.
Steps:
- Keeping your arms straight, bring them in front of you, raise them over your head, then continue the motion behind your back and down to the initial position.
- Keep circling your arms as described in step 1.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/995/view/'),
  ('1a40cc23-4609-4951-9b76-237715ae85ed', 'Backward shoulder rotation', null, 'Starting position:
Sit or stand with your back straight.
Steps:
- Place your hands on your shoulders.
- Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1005/view/'),
  ('d301d901-a2c6-4916-b09e-07ab7a3c8519', 'Bag training', 'Shoulders, Chest, Trapezius', 'Bag training improves muscle definition of: deltoids; rear deltoids; triceps; biceps, as well as being a great cardio exercise', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1092/view/'),
  ('36391719-d4ad-4e0f-991f-8eafd5947108', 'Ball crunches', 'Abs', null, null, 'wger', 'CC-BY-SA 4', 'Konsumopfer', 'https://wger.de/en/exercise/165/view/'),
  ('a1e8759d-72b9-422f-87a8-9d316fa18498', 'Ball Slams', 'Lats, Obliquus externus abdominis, Abs', '- Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture.
- Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive.
- Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down.
- Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time.', null, 'wger', 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1525/view/'),
  ('d87059cf-b18d-42f0-94a1-370cda0eedfd', 'Band Finger Extensions', null, 'Put a small rubber band around all five fingertips. Spread your fingers and thumb open as wide as possible against the band, hold for a second, then close slowly. This trains the extensor muscles that open the hand and balances heavy gripping, which helps keep the elbows and wrists healthy.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2742/view/'),
  ('83650b79-add8-4846-b114-b4f28d96495a', 'Band pull-apart with external rotation', 'Shoulders', 'Stand tall with your feet shoulder-width apart, chest out, and shoulders back.
Hold the resistance band with both hands, palms facing up or facing each other, depending on the band type.
Bend your elbows at a 90-degree angle and glue your upper arms to your sides.
The band should have some tension in the starting position, with your hands closer together in front of your stomach.
Rotate Outward: While keeping your elbows tucked into your sides, slowly move your hands away from each other, stretching the band.
Squeeze: Squeeze your shoulder blades together and down as you rotate your hands outward.
Range of Motion: Rotate your hands as far outward as you comfortably can without allowing your elbows to leave your sides.
Hold: Hold the end position for 1–2 seconds to maximize muscle engagement.
Return: Slowly and with control, bring your hands back to the starting position.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1826/view/'),
  ('f18eb684-9a9b-4566-9771-e22a87d536b1', 'Band pull-aparts', null, '- Hold the band with your arms extended in front of you at shoulder height.
- Keep your elbows slightly bent but fixed throughout the movement.
- Pull the band apart by spreading your arms until the band touches or comes close to your chest.
- Slowly bring your arms back to the starting position, controlling the tension on the band.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'schwolfar', 'https://wger.de/en/exercise/1380/view/'),
  ('3096b34e-1781-4f99-8187-d9acac8e712b', 'Band Terminal Knee extension', 'Quads', 'This is an end range strengthening exercise for the knee extensors. Start by looping a band around the back of one knee and anchoring the other end to a stable surface in front of you. Stand in a split stance with the banded knee bent and placed as the front leg. Straighten the knee to pull against the bands resistance and maintain a contraction in your quadriceps for up to 5 seconds before releasing.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'Rehab Hero', 'https://wger.de/en/exercise/2494/view/'),
  ('fcdc26c0-a20d-4b93-a629-2a3a15eae426', 'Banded Ankle Mobility', null, 'Anchor a resistance band low behind you, for example at the bottom of a rack, and loop it around the front of your ankle, just above the foot.
Get into a half-kneeling position with the banded foot in front, so that the band pulls your ankle backwards.
Keeping your heel on the floor, drive your knee forward over your toes, then return under control. Repeat for several reps and switch sides.', null, 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1865/view/'),
  ('8cc84753-e638-4c43-91c6-51c097813ca4', 'Banded Clamshell', 'Glutes, Abs', 'Position
Side plank with the elbow and the forearm on the ground and the legs slightly bent. Stretch a doubled-up resistance band between your thighs, just above the knee.
Execution
Lift
your upper knee while keeping your feet close together, like a “shell
opening,” then slowly return to the starting position. Keep your core
stable and your hips aligned.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1842/view/'),
  ('8270bfb7-0264-4f79-aa3d-1ceed134b5d0', 'Banded Front Raise', 'Shoulders', 'Stand on the middle of a resistance band with feet about hip-width apart, holding one end in each hand in front of your thighs. Keeping your arms straight with a slight bend in the elbows, raise your hands forward to shoulder height, then lower slowly under control. Can be done with both arms together or alternating. Use a heavier band or shorten the band to increase resistance.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2622/view/'),
  ('f47c4ad6-fe45-4409-93dd-e889d6a1aa89', 'Banded Monster Walk', 'Glutes', 'A banded walking drill for the glutes and hip stabilisers. Place a mini band around both thighs just above the knees, or around the ankles for a harder version. Stand with feet hip-width apart so the band is under tension, then sink into a quarter-squat with the chest up. Walk forward with small diagonal steps, pushing each leg out against the band and keeping the knees tracking over the toes rather than letting them fall inward. Walk forward for the prescribed number of steps, then walk backward to return, keeping the band under tension throughout.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2665/view/'),
  ('add364ed-4444-4752-9a22-d85d58199fe5', 'Banded Scapular Retraction', 'Shoulders, Trapezius', 'Attach one end of resistance band to wall/upright/... at shoulder height. Insert arm into the loop, at the tricep. Step back until band is pulled straight. Pull back elbow and shoulder against the resistance of the band.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'hurr99', 'https://wger.de/en/exercise/1877/view/'),
  ('4c317795-c301-4081-9f96-6036682f80c1', 'Banded Shoulder Drills', 'Shoulders, Chest, Trapezius', '- Attach a resistance band to something solid behind you. Stand away from it, holding it in your hand so it is taut.
- Perform the shoulder mobility and rotation drills shown in the video: https://www.youtube.com/watch?v=zdwEWchSjrI', 'Resistance band', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1838/view/'),
  ('a6bced3c-72f5-42a3-9438-5569d46f49fd', 'Barbell Ab Rollout', 'Obliquus externus abdominis', 'Place a barbell on the floor at your feet.
Bending at the waist, grip the barbell with a shoulder with overhand grip.
With a slow controlled motion, roll the bar out so that your back is straight.
Roll back up raising your hips and butt as you return to the starting position.', 'Barbell', 'wger', 'CC-BY-SA 4', 'sevae', 'https://wger.de/en/exercise/41/view/'),
  ('e9e7372c-b5c1-45d9-ae5c-b1aa0fc2e2ce', 'Barbell Clean and press', 'Shoulders, Chest', 'This exercise involves lifting a barbell from the ground to the shoulders, then pressing it overhead. It is a compound movement that targets multiple muscle groups, including the legs, back, shoulders, and arms. It is often used in strength and conditioning programs to improve overall power and athleticism.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1638/view/'),
  ('5d0e0a8b-1940-4034-b4ae-b965859f1ff0', 'Barbell Full Squat', 'Hamstrings, Glutes, Quads', '- The barbell full squat is a compound exercise that targets multiple muscle groups in the lower body, including the quadriceps, hamstrings, and glutes.
- Proper form is crucial for maximizing results and preventing injuries during the barbell full squat. This includes maintaining a shoulder-width stance, creating whole body tension, controlling your descent, and maintaining proper depth and knee positioning.
- Assistance moves such as the front squat, goblet squat, split squat, and Bulgarian split squat can help improve your performance in the barbell full squat by targeting specific muscle groups and improving overall technique.
- To achieve new personal records in your back squat, gradually increase weight over time, vary rep ranges and sets to stimulate muscle growth, and prioritize rest and recovery between training sessions.', 'Barbell', 'wger', 'CC-BY-SA 4', 'fabrice', 'https://wger.de/en/exercise/1801/view/'),
  ('dae6f6ed-9408-4e62-a59a-1a33f4e8ab36', 'Barbell Hack Squats', 'Quads', 'Place a barbell on the floor just behind your heels. Stand with your feet about hip-width apart or closer, keep your chest up and your back straight, and squat down to grip the bar behind you with straight arms.
Stand up by extending your knees and hips, sliding the bar up along the back of your legs. Lower it under control to complete the rep.', 'Barbell', 'wger', 'CC-BY-SA 4', 'BePieToday', 'https://wger.de/en/exercise/43/view/'),
  ('04e7d7e4-f8d2-406d-97df-3df3bceec22c', 'Barbell Lunges Standing', 'Quads', 'Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg.
Remember to keep good posture.', 'Barbell', 'wger', 'CC-BY-SA 4', 'Mikko Ruohola', 'https://wger.de/en/exercise/46/view/'),
  ('072a9fa8-1028-47b3-b958-d8052c6b8661', 'Barbell Lunges Walking', 'Glutes, Quads', null, 'Barbell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/802/view/'),
  ('67c26c9b-32f3-4b8b-b13a-4d8be4803975', 'Barbell Reverse Wrist Curl', null, 'Sitting on a bench, grab a barbell with your palms facing down and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees.
Curl your knuckles towards your face, lifting the barbell. Pause for a moment in the top position, then slowly return the barbell to the starting position.', 'Barbell, Bench', 'wger', 'CC-BY-SA 4', 'burenl', 'https://wger.de/en/exercise/48/view/'),
  ('72129e4f-df97-4869-9561-33a1ba3c9186', 'Barbell Romanian Deadlift (RDL)', 'Hamstrings, Glutes', 'Execution
-
Hinge at the hips:
- Push your hips backward, keeping a slight bend in the knees (soft knees).
- Lower the barbell along the front of your thighs/shins while maintaining a neutral spine.
- Keep the bar close to your body.', 'Barbell', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1700/view/'),
  ('6ce25688-ae91-4dc7-9b17-0b66a47151fa', 'Barbell Row (Overhand)', 'Lats', 'Execution
-
Starting position:
- Hold the barbell with arms fully extended toward the floor.
- Maintain tension in your lats and back muscles.', 'Barbell', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1698/view/'),
  ('3c2b5e2d-bd9d-43e8-8b5f-e6363331faa1', 'Barbell Row (Underhand)', 'Lats', 'Execution
-
Starting position:
- Hold the barbell with arms fully extended toward the floor.
- Maintain tension in your lats and back muscles.', 'Barbell', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1699/view/'),
  ('b2dd2bfd-dcc8-4a92-84eb-c0009ec68a53', 'Barbell Row (Underhand) (Custom)', 'Lats', 'Perform Barbell Row (Underhand) with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'Barbell', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2719/view/'),
  ('64b50772-c73d-4833-8518-947a648fa623', 'Barbell Silverback Shrug', 'Trapezius', '- Stand with your feet shoulder width apart holding the barbell with both hands in front just past shoulder width.
- Bend forward at the hips with a slight bend in your knees, keeping your back straight.
- Engage your shoulder blades, as if you are trying to touch them together.
- Release the shrug.
Description taken from MuscleWiki', 'Barbell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1925/view/'),
  ('928eeae3-d849-4605-a470-048ca259a8c5', 'Barbell Step Back Lunge', 'Quads', '- Stand with your feet hip-width apart, holding a barbell on your upper back.
- Keep your back straight, chest up, and core engaged.
- Take a step back with one leg and lower your body by bending both knees. Ensure that your back knee nearly touches the ground.
- Push off your back foot to return to the starting position.
- Repeat the movement with the other leg.
Continue alternating between legs for the desired repetitions.', 'Barbell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1830/view/'),
  ('13234b53-ea0c-41f1-9069-776865ea8eff', 'Barbell Triceps Extension', 'Triceps', 'Position barbell overhead with narrow overhand grip.
Lower forearm behind upper arm with elbows remaining overhead. Extend forearm overhead. Lower and repeat.', 'Barbell', 'wger', 'CC-BY-SA 4', 'sevae', 'https://wger.de/en/exercise/50/view/'),
  ('cfb6a754-57be-431b-b8d0-d9963120bd5a', 'Barbell Wrist Curl', null, 'Sitting on a bench, grab a barbell with your palms facing up and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees. Perform the movement by curling your palms and wrists towards your face.
Pause for a moment in the top position, then slowly return the barbell to the starting position.', 'Barbell, Bench', 'wger', 'CC-BY-SA 4', 'burenl', 'https://wger.de/en/exercise/51/view/'),
  ('a5d1f45b-ff07-45d7-a699-a654f9328934', 'Battle Ropes', 'Hamstrings, Glutes, Lats, Obliquus externus abdominis, Quads, Abs', '- Hold the ends of the rope at arm''s length in front of your hips with your hands shoulder-width apart.
- Brace your core and begin alternately raising and lowering each arm explosively.
- Keep alternating arms for three to four sets of 1 to 2 minutes.', null, 'wger', 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1524/view/'),
  ('06968051-a818-489c-9fbb-ddb94a001245', 'Bayesian Curl', 'Biceps', 'Cable curl with the shoulder extended backwards, which puts the biceps in a stretched position at the start of the movement.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'aahuja', 'https://wger.de/en/exercise/1493/view/'),
  ('b4dc15da-4d4d-4a93-a30a-74aaf99192ff', 'Bear crawl pull through', 'Shoulders, Glutes, Quads, Abs', 'Place a dumbbell at around hip level and assume a bear crawl position. Push the knees off the floor and hold.
With the opposite hand reach for the dumbbell and pull it to the other side. Place your hand back on the floor and repeat with your other hand.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1687/view/'),
  ('b7267f90-8706-442b-b918-507e16092b8e', 'Bear Walk 2', 'Shoulders, Calves, Chest, Abs, Serratus anterior, Soleus, Triceps', '-Rest your weight on your palms and the balls of your feet, not dissimilar to normal pushup position
-Move by stepping with your R palm and L foot, then your L palm and R foot.  Basically, walk like a lumbering bear.
-Move as fast as you can.  Measure your reps/sets in either distance (i.e. 40 yards) or time (i.e. 45 seconds)
-Works your Pecs, Deltoids, Triceps, Traps, Lats, Abs and Lower Back, Hip Flexors, Quads, Glutes and Calves', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/57/view/'),
  ('57018827-f344-4627-88e5-03e4f2f49859', 'Behind the Back Cable Lateral Raise', 'Shoulders', 'Lateral raises have long been a staple for building capped delts, and lifters use everything from dumbbells and bands to machines and single-arm variations to make them grow.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'LEBRERO', 'https://wger.de/en/exercise/1807/view/'),
  ('e9f3446f-ca98-4bf2-817c-0dacd123cecd', 'Belt Squat', 'Glutes, Quads', 'Belt Squat: a squat variation done with a belt attached to a loading machine or platform so the weight is supported at the hips instead of on the spine. It mainly trains the quads and glutes, with much less lower-back fatigue than a barbell squat. Use a full range of motion, keep the torso upright, and drive through the mid-foot.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1935/view/'),
  ('fbeb1fd5-d259-4a85-a993-03569d8146dc', 'Bench Dips On Floor HD', 'Biceps, Brachialis, Triceps', 'Triceps dips on floor are a compound exercise as they worked multiple muscle groups simultaneously. Although this bodyweight exercise mainly targets the triceps, it also hits your chest and front of your shoulder.
Triceps dips on floor are one of the most effective exercises to increase arm strength and also build lean muscle in your upper arms.
Triceps dips on floor are a closed kinetic chain exercise and express that you do the movements around a fixed point. It increases compression force on your joints thereby improving stability.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1320/view/'),
  ('3717d144-7815-4a97-9a56-956fb889c996', 'Bench Press', 'Chest', 'Lay down on a bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.
If you train with a high weight it is advisable to have a spotter that can help you up if you can''t lift the weight on your own.
With the width of the grip you can also control which part of the chest is trained more:
- wide grip: outer chest muscles
- narrow grip: inner chest muscles and triceps', 'Barbell, Bench', 'wger', 'CC-BY-SA 3', 'sistab2', 'https://wger.de/en/exercise/73/view/'),
  ('a79ff861-99a8-4256-8154-f08feb89ba98', 'Bench Press (Custom)', 'Chest', 'Perform Bench Press with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'Barbell, Bench', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2700/view/'),
  ('20d8df5a-c9d6-4c69-bdf2-d97af68ac83f', 'Bench Press Isometric', 'Shoulders, Chest, Triceps', 'A bench press isometric hold is a static strength exercise where you pause and hold a barbell or dumbbells either at your chest, mid-press, or at lockout without moving for a set time', 'Barbell, Bench', 'wger', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2536/view/'),
  ('3db63138-a047-4a4d-b616-1a0b7dfca105', 'Bench Press Narrow Grip', 'Triceps', '- Setup: Lie flat on the bench and grip the bar at shoulder-width (closer than a standard bench press).
- Descent: Lower the bar with control to your lower chest.
- Form: Keep your elbows tucked in tight against your torso—do not let them flare out.
- Ascent: Press the bar straight back up, squeezing your triceps at the top.', 'Barbell, Bench', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/76/view/'),
  ('28321cf3-70e6-48a4-ade1-d11382180cb3', 'Benchpress Dumbbells', 'Chest', '-
Setup and Starting Position: Sit at the end of a flat bench with a dumbbell resting vertically against each thigh. Carefully lean back while driving the dumbbells toward your chest with your knees.
-
The “Leg Drive” and Posture: Plant your feet firmly on the floor. Retract your shoulder blades (press them together against the bench) and maintain a slight natural lumbar curve.
-
Starting Position: Push the dumbbells toward the ceiling. Your wrists should be aligned with your elbows. Rotate the dumbbells slightly inward (about 45 degrees) so that your elbows do not splay out too far to the sides, thereby protecting your shoulders.
-
Eccentric Phase (Lowering): Lower the dumbbells in a controlled manner toward the sides of your chest. Your elbows should lower at an angle of about 45–60 degrees relative to your body. Feel the stretch in the lower part of your chest.
-
Concentric Phase (Lift): Push the weight upward in a slight arc (toward the center), without letting the dumbbells collide at the top or fully locking out your elbows to maintain muscle tension. Exhale as you lift.
Translated with DeepL.com (free version)', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/75/view/'),
  ('01271ea0-088c-4e2b-95ad-876af7127057', 'Bent High Pulls', 'Trapezius', 'Bend over slightly while holding two dumbbells.  Pull the dumbbells up to your chest, keeping your elbows as high as you can.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'lakerbeezel', 'https://wger.de/en/exercise/79/view/'),
  ('7ef2e00e-067c-48e0-9b42-3d622e0df8a4', 'Bent over Cable Flye', 'Chest', 'Holding your upper body at an approximate 105° angle.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1469/view/'),
  ('94a5c406-7bcd-47f3-9687-bdf92a763932', 'Bent Over Dumbbell Rows (Single Arm)', 'Lats', 'With dumbbells in hand, bend at the hip until hands hang just below the knees (similar to straight-legged-deadlift starting position). Keep upper body angle constant while contracting your lats to pull you ellbows back pinching the shoulder blades at the top. Try not to stand up with every rep, check hands go below knees on every rep.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'sebk', 'https://wger.de/en/exercise/81/view/'),
  ('3642933c-d078-4fb6-a544-d1772fa0cc9d', 'Bent Over Dumbbell Rows (Two Arms)', 'Lats, Trapezius', 'How to Perform It
- Hold a dumbbell in each hand with a neutral or overhand grip.
- Hinge at the hips, pushing your glutes back, until your torso is roughly 45–75 degrees to the floor. Keep a slight bend in your knees.
- Let the dumbbells hang directly below your shoulders with arms fully extended.
- Keep your back flat, chest up, and core braced — avoid rounding your spine.
- Pull the dumbbells up toward your ribcage/hips, driving your elbows back and squeezing your shoulder blades together at the top.
- Pause briefly at the top of the movement.
- Lower the dumbbells back down under control to the starting position.
- Repeat for the desired number of repetitions.
Key Coaching Cues
- Hinge from the hips, not the lower back
- Keep the spine neutral throughout — no rounding
- Lead with the elbows, not the hands
- Avoid using momentum or jerking the weight up
- Control the eccentric (lowering) phase rather than letting the weights drop', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'karthikrrk', 'https://wger.de/en/exercise/2669/view/'),
  ('30f87d3f-4e57-4d28-b124-8dc64d35eb03', 'Bent Over Row', 'Lats', 'Standing with the torso bent forward from the hips at roughly 45 degrees, back straight. Hold two dumbbells with an overhand grip, arms hanging below the shoulders. Pull the dumbbells along the body toward the pelvis, elbows close to the torso, briefly squeezing the shoulder blades together at the top. Lower under control. Primary muscle: lats. Keep the torso stable throughout the movement, no arching of the lower back.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'lleeaa', 'https://wger.de/en/exercise/2762/view/'),
  ('f3f4e9c5-9bf6-43f6-a2cf-798507a50293', 'Bent over row to external rotation', null, 'Starting position:
Stand behind a chair or in front of a table. Bend at the waist to put your forehead on the chair''s headrest or table, keeping your back straight. Your arms should be hanging straight down, pointed at the floor.
Steps:
- Bring your elbows up to shoulder height. Your forearms should be pointing down, perpendicular to your biceps. Your biceps should be at the same height as your back and perpendicular to your spine.
- Hold for a bit.
- Rotate at your elbows to bring your hands as far up as you can.
- Hold for a bit.
- Rotate at your elbows back to the previous position.
- Bring your arms down to the original position.
- Repeat.', null, 'wger', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1082/view/'),
  ('4af6dbd9-8991-484b-9810-68f117c21edf', 'Bent Over Rowing', 'Lats', '- Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.
- Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.
- Then inhale and slowly lower the barbell back to the starting position.
- Repeat for the recommended amount of repetitions.', 'Barbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/83/view/'),
  ('2f0ddf9a-f520-4c55-8883-f0d4a789f481', 'Bent Over Rowing Reverse', 'Lats', 'The same as regular rowing, but holding a reversed grip (your palms pointing forwards):
Grab the barbell with a wide grIp (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise.
Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.', 'Barbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/84/view/'),
  ('4ce9740f-313d-4419-8a23-6c884d3a1a17', 'Bent-knee Iron Cross', null, 'Bent-knee Iron Cross
Part of: Limber 11
Source: Joe DeFranco
Prescription: 5-10 reps each side
Type: dynamic', null, 'wger', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1953/view/'),
  ('abdd2b41-0c30-4ec1-8d14-f6dc5deb3561', 'Bent-Leg Hamstring Stretch', null, 'Lie on your back with one leg straight on the floor. Hold the other leg behind the knee or the back of the thigh and pull it towards your chest, keeping the knee bent, until you feel a stretch in the hamstrings.
Hold the position while breathing calmly, then switch sides.
See this instructional video from Stretch Therapy: https://www.youtube.com/watch?v=CrF2iMnn09w', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1840/view/'),
  ('6f79b381-98a4-40d5-8a45-3bb0558be6fe', 'Bent-over Lateral Raises', null, 'Sit on bench while holding weights. Bend forward as far as possible, with arms slightly bent at the elbow. Perform a lateral raise while maintaining the bend in your elbow.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'apeschel', 'https://wger.de/en/exercise/82/view/'),
  ('8bb42000-834f-48ab-af5c-0c31d94e0181', 'Biceps Close Grip Pull Down', 'Biceps', 'On a lat pull down machine, hold the bar keeping your hands relatively close. Use an underhand grip (I.E.: the back of your hand must be facing the machine). Then pull down the bar in a straight line towards the ground. Make sure your biceps are the main drivers of the motion. You will probably feel your shoulders and lats working, but make sure your biceps are working more.', null, 'wger', 'CC-BY-SA 4', 'daniel.escada', 'https://wger.de/en/exercise/1280/view/'),
  ('e68f6d51-fe02-4175-b277-dec0c1521f36', 'Biceps Curl Machine', 'Biceps', 'The biceps curl machine is designed to isolate the biceps muscles and provide a controlled range of motion. Sit on the machine with your back against the pad and adjust the seat so your arms are aligned with the machine''s handles or pads. Grip the handles firmly, keeping your elbows fixed in place, and curl the handles upward by contracting your biceps. Slowly lower the handles to the starting position, maintaining control throughout the movement.', null, 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1424/view/'),
  ('bcb7020c-8678-496d-8f4d-aad0e233a5bd', 'Biceps Curl With Cable', 'Biceps', 'Stand around 30 - 40cm away from the cable, the feet are firmly on the floor. Take the bar and lift the weight with a fast movements. Lower the weight as with the dumbbell curls slowly and controlled.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/95/view/'),
  ('7b99a081-6b1a-4aa5-b86a-5a935d083a35', 'Biceps Curls With Barbell', 'Biceps', 'Hold the Barbell shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement.
Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).', 'Barbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/91/view/'),
  ('1ae6a28d-10e7-4ecf-af4f-905f8193e2c6', 'Biceps Curls With Dumbbell', 'Biceps', 'Hold two dumbbells, the arms are streched, the hands are on your side, the palms face inwards. Bend the arms and bring the weight with a fast movement up. At the same time, rotate your arms by 90 degrees at the very beginning of the movement. At the highest point, rotate a little the weights further outwards. Without a pause, bring them down, slowly.
Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/92/view/'),
  ('c41b4b70-c605-4ec1-bf94-d8d73b0e5f46', 'Biceps Curls With Dumbbell (Custom)', 'Biceps', 'Perform Biceps Curls With Dumbbell with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2701/view/'),
  ('42227131-9b1e-4220-b082-c523f0651057', 'Biceps Curls With SZ-bar', 'Biceps', 'Hold the SZ-bar shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement.
Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).', 'SZ-Bar', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/94/view/'),
  ('596b9d2d-0f01-41a0-97e1-1839ffdb824d', 'Biceps with TRX', 'Biceps', 'Grab the handles of the TRX straps, lean your body back, arms and legs extended, with your body positioned in a single straight line. (This is an arm exercise, not an abdominal one.)', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/958/view/'),
  ('fcf5039b-7784-4f82-830a-b213b597a646', 'bicycle crunches', 'Abs', 'Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1412/view/'),
  ('6349365e-e901-4280-a1b7-65734986f47d', 'Bird Dog', 'Abs', 'The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control.
- Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral.
- Extend your right arm forward and left leg backward simultaneously, keeping hips square.
- Pause briefly at full extension while engaging your core and glutes.
- Return to the starting position and repeat on the opposite side', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1572/view/'),
  ('b77a48f4-28bd-424d-9f1c-f141d47a285f', 'Bird Dog (Custom)', 'Abs', 'On all fours, extend opposite arm and leg, keep the pelvis level and the spine neutral, move slowly under control, return to the start without letting the lower back sag.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2753/view/'),
  ('da6ab4d8-edd2-428d-b194-fb15948d3fd5', 'Bizeps Curls Trifecta', 'Biceps', 'This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You
alternate between three curl variations that each accomplish different goals,
and you’ll keep the set going beyond the usual 8-12 rep range which gives
us that intensity.
- For the Supinated Cross Body
Curl, supinate the forearm with palms facing toward the ceiling and
forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.
- For the Pronated Cross Body
Curl, pronate the forearm with palms facing toward the floor (pronated
grip or overhand grip) and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.
- For the No Money Curl, you’ll
curl the dumbbell as you outwardly rotate the shoulder. Lift the inner-facing weight of the dumbbell towards your outer side of the shoulder.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1483/view/'),
  ('64ebb7a5-15ec-48dd-8f82-47cdb022f215', 'Black Widow Knee Slides', 'Obliquus externus abdominis, Abs', 'In
this bottom-up rotation exercise movement, you’ll cross your knee over and
drive it into that opposite elbow. Start in high plank position (or tabletop
position) with hands directly beneath your shoulders. Lift the left knee toward
the right arm and slide it up the forearm to get more of that posterior pelvic
tilt and engagement of the abdominal muscles. Then do the opposite side,
bringing your right knee toward your left hand.', null, 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1475/view/'),
  ('1fe103e2-1def-41de-8eab-e2e11296446d', 'Blackroll', null, '- Controlled movements
- Slow movements
- Don''t use momentum', null, 'wger', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1363/view/'),
  ('24f988e7-51eb-44f5-92f2-d4e0199c2269', 'Blaze', 'Shoulders, Glutes, Chest, Quads', 'BLAZE is a full-body HIIT workout. Designed to supercharge your cardio fitness and strength. Delivered in its own purpose-built studio, BLAZE is a unique mix of martial arts, intense cardio and strength training.', 'Bench, Dumbbell, Kettlebell', 'wger', 'CC-BY-SA 4', 'ricwheatley', 'https://wger.de/en/exercise/1630/view/'),
  ('c4b2ed05-38d5-47fc-9ad1-c23f09fddd61', 'Bobbing Exhale Drill', 'Abs', 'Stand in chest-deep water. Take a breath, submerge your face fully, and exhale slowly and completely through your nose and/or mouth the whole time you''re underwater — a gentle humming sound can help keep the exhale steady and controlled. Once you''re empty of air, lift your head, take a fresh breath, and go back under. Repeat continuously. The goal is training your body that all your exhaling happens underwater, so all you need to do at the surface is inhale.', null, 'wger', 'CC-BY-SA 4', 'Imported from swim plan', 'https://wger.de/en/exercise/2482/view/'),
  ('d551f24d-44fe-4761-9448-edf14d627827', 'Body-Ups', 'Triceps', '- Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.
- Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.
- Slowly lower your forearms back to the ground by allowing the elbows to flex.
- Repeat as needed.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/112/view/'),
  ('a94623fc-518f-4a74-947b-febd086264bf', 'Bodyweight Biceps Curl', 'Biceps', 'Set up under a straight bar (around waist or chest height). Grip the bar with your palms facing you (supinated grip), hands about shoulder-width apart. Lean back with straight arms so that your body is at an angle to the ground. Keeping your elbows high and close to the bar, pull your upper body toward the bar by flexing your elbows, similar to a biceps curl. Lower yourself back down in a controlled manner. Keep your core tight and movement slow to maximize tension on the biceps.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'tenebrizz', 'https://wger.de/en/exercise/1608/view/'),
  ('f9a0a918-3c0c-464e-bbba-1bd309d4a519', 'Bodyweight lunge HD', 'Quads', 'Bodyweight lunges are an effective calisthenic exercise for
strengthening the lower body, improving balance and stability, and
developing functional strength. They are a popular choice for bodyweight workouts, home workouts, and can also be included as part of a larger strength training routine.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1324/view/'),
  ('edc3f6b7-96b0-4967-90d7-bba9d7d442cb', 'Bodyweight Squat HD', 'Quads', 'Squat is a type of bodyweight exercise. It is one of the most popular exercises for strength and muscle growth. Squat is particularly effective for focusing on the muscles of the leg and hips.
Squat are an easy exercise for beginners to do. It can help strengthen leg muscles, tighten hip muscles and burn calories to lose weight.
It tightens the butt and legs. Squats are very effective for firming and strengthening your legs by acting on the gluteus,hip flexors, quadriceps, hamstrings and inner thigh muscles. Also, bodyweight squats can help shape your glutes and butt.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1312/view/'),
  ('6f919d6d-e8b2-4aac-bc43-fd6184978b70', 'Box Handstand Push-up', 'Shoulders, Chest, Triceps', 'Pike push-up with legs on an elevated surface. Progression to handstand push-up.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Jarda', 'https://wger.de/en/exercise/2621/view/'),
  ('002c6a4f-28ac-4b07-8e94-053e5b05d52b', 'box jumps', 'Glutes', 'Jump from a standing position onto the box, stretch your body, then step down again (do not jump)', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'tekknokrat@gmx.de', 'https://wger.de/en/exercise/1373/view/'),
  ('151434a5-c046-459f-a3a9-c3125075856f', 'Box squat', 'Glutes, Quads, Soleus', '- Set up the box: Position the box behind you, about 3 feet from a squat rack if you''re using a barbell. Choose a height that allows you to squat down and gently tap your glutes on the box with your back straight.
- Stand with proper form: Stand with your feet shoulder-width apart, toes pointed slightly outward. Engage your core and keep your back neutral. If using a barbell, rack it at shoulder height.
- Lower down: Sit back as if going to sit on a chair, bending your knees and lowering your hips towards the box. Keep your core tight and back straight throughout the movement.
- Controlled descent: Descend in a controlled manner until your glutes gently touch the box. Don''t plop down.
- Pause and press up: Briefly pause at the bottom with your back straight and core engaged. Then, press through your heels to drive yourself back up to the starting position.
Improvements in coordination, balance and endurance, toning of the leg and buttock muscles and an overall increase in bone density eliminating the risk of osteoporosis.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/977/view/'),
  ('0829749c-de42-49a5-a24b-451b0eac8627', 'Boxing', 'Shoulders, Triceps', 'Bag workout for boxing skill development and cardio improvement', null, 'wger', 'CC-BY-SA 4', 'SAH', 'https://wger.de/en/exercise/2542/view/'),
  ('8c6428f3-d41d-4ffc-8444-bb9b823bc42b', 'Braced Squat', 'Quads', 'Stand with feet slightly wider than shoulder-width apart, while standing as tall as you can.
Grab a weight plate and hold it out in front of your body with arms straight out. Keep your core tight and stand with a natural arch in your back.
Now, push hips back and bend knees down into a squat as far as you can. Hold for a few moments and bring yourself back up to the starting position.', null, 'wger', 'CC-BY-SA 4', 'sevae', 'https://wger.de/en/exercise/124/view/'),
  ('a94c635d-096c-45a8-a68c-64941d0b6ba4', 'Bretzel stretch', 'Glutes', 'How to Perform the Bretzel Stretch
- Starting Position: Lie on your back on a flat surface, such as a mat. Bend your knees and place your feet flat on the ground.
- Leg Positioning: Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee. Your left leg should remain flat on the ground.
- Arm Positioning: Extend your left arm out to the side at shoulder height, keeping it straight. Use your right hand to gently pull your right knee towards the floor on the left side of your body.
- Stretching: As you pull your knee down, try to keep your left shoulder flat on the ground. You should feel a stretch in your hip, lower back, and possibly your chest.
- Hold the Position: Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch. Switch sides and repeat the process.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1577/view/'),
  ('a6d880e5-bdbe-408f-b762-3b41c7fff834', 'Bronco', null, 'Fitness test for rugby.
5 x shuttle runs of 20m, 40m, and 60m (20yd, 45yd, 65yd/far 45yd mark)
Complete as fast as possible', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'MU5H', 'https://wger.de/en/exercise/1579/view/'),
  ('46a6abaf-13ed-4b3a-8318-1022cdb5b8da', 'Bulgarian Split Squat (Custom)', 'Quads', 'Perform the Bulgarian split squat with an upright torso, rear foot on a bench, lower until the front thigh is parallel, keep the knee over the toes, hold a rack for balance if needed.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2750/view/'),
  ('7ce489d2-1948-46de-aa80-277b2ca737aa', 'Bulgarian split squats left', 'Glutes, Quads', '- Stand tall in front of a chair and take a large step. Put the upper part of one of your feet on the chair.
- Bend the front knee, balancing with arms until the back knee almost touches the ground.
- Push back to the starting position and repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/988/view/'),
  ('44afe80f-1ab2-4149-adbf-d8e0ece990ce', 'Bulgarian split squats right', 'Glutes, Quads', '- Stand tall in front of a chair and take a large step. Put the upper part of one of your feet on the chair.
- Bend the front knee, balancing with arms until the back knee almost touches the ground.
- Push back to the starting position and repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/989/view/'),
  ('60d2c34b-43a1-48a3-b43b-160e4c0157f2', 'Bulgarian Squat with Dumbbells', 'Glutes, Quads', 'The Bulgarian split squat consists of performing a squat on one leg with the rear foot resting on a raised platform. Elevating your back leg on a bench creates instability and increases the range of motion of the exercise.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1706/view/'),
  ('48ee1385-47c5-4821-8b6a-57fac6130776', 'Burpees', null, 'Jump, lay down on your chest, do a pushup then jump, repeat', null, 'wger', 'CC-BY-SA 4', 'er0355', 'https://wger.de/en/exercise/132/view/'),
  ('3d85bdce-e1a9-48a2-b14d-8032820ebf25', 'Bus Drivers', 'Shoulders', 'Sitting with a Weight Plate, used as wheel, in both hands; raised slightly below eye level', null, 'wger', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/915/view/'),
  ('4885c051-154b-4a9b-a0fe-ccb70a652fa4', 'Butchers Block Stretch', 'Lats', '- Kneel down with the hands together
- Rest the elbows on a bench in front of you and lower the chest down
- Keep the elbows bent with good posture and hold', 'Bench', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1710/view/'),
  ('99449eae-0eae-44ab-a57f-fc094bbdda13', 'Butterfly', 'Chest', 'Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/135/view/'),
  ('f77b2128-1dfd-4434-923d-31ffe4881100', 'Butterfly (Custom)', 'Chest', 'Perform Butterfly with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2702/view/'),
  ('80ff0a3a-ae45-497d-8c27-2b12e3b6e1b8', 'Butterfly Narrow Grip', 'Chest', 'The movement is the same as with a regular butterfly, only that the grip is narrow:
Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/137/view/'),
  ('a6605e9c-887d-45e0-8282-617a8ec5fea2', 'Butterfly Reverse', 'Shoulders', null, null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/139/view/'),
  ('cf94c288-e2e7-4a0a-bfe2-c96e92e7cb34', 'Butterfly Reverse (Custom)', 'Shoulders', 'Perform Butterfly Reverse with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2703/view/'),
  ('1bb3bbaf-2dc2-4651-95db-71faf5304075', 'Butterfly Sit Up', 'Obliquus externus abdominis, Abs', 'In
this midrange exercise your arm muscles provide you with a little bit of
momentum to help to get you off the ground. You also open them up in overhead
position which engages the upper back. Start
lying with feet flat on the ground, knees at an angle, arms crossed in towards your chest. Using
your ab muscles, bring your upper body off the ground as you open your arms
into goal post position, then slowly lower yourself back down to return to
starting position.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1476/view/'),
  ('df3a6900-55c1-435b-bcde-7510dc229b20', 'Butterfly Stretch', null, '- Sit in a prayer position with the soles of your feet gently pressed together.
- Use your hands to slowly pull your feet inwards towards your groin. Hold for as long as required.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1843/view/'),
  ('de06856d-109d-4bef-acab-0918028cea36', 'Butterfly Superman', 'Trapezius', 'Lie on stomach, intertwine fingers behind the head and start raising your head and raise elbows as far as they go.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1908/view/'),
  ('1fcde579-87ec-4cb6-b5a3-7fe80fb49159', 'Cable Back Pressure', 'Biceps', 'Set a cable at chest height and stand side on, holding the handle with your elbow bent about ninety degrees in front of you, like an arm wrestling setup. Pull the handle toward your body using your biceps and back, keeping the wrist cupped, then return slowly. This trains the hook or back pressure used in arm wrestling.', null, 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2734/view/'),
  ('b2865908-b93e-4507-ada4-a5bb9317566c', 'Cable Chest Press - Decline', 'Chest', 'Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight decline and aiming towards the center of your chest.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1656/view/'),
  ('e22c4320-7753-49c6-b7f7-4be21b025fb6', 'Cable Chest Press - Incline', 'Chest', 'Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight incline and aiming towards the center of your chest.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1660/view/'),
  ('b1bf02cf-17b2-4bfc-a5b0-4ff7a2768dbb', 'Cable Concentration Curl', 'Biceps, Brachialis', 'The concentration curl is a classic exercise for building the biceps one arm at a time. It can be performed bent over or kneeling, but is more often performed seated on a bench. It''s great for emphasizing the biceps peak and is often used to finish a biceps workout', 'Cable machine', 'wger', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/1109/view/'),
  ('b16e3e5d-8401-4d2b-919c-15b536f9ec5e', 'Cable Cross-over', 'Chest', 'Begin with cables at about shoulder height, one in each hand. Take a step forward so that one foot is in front of the other, for stability, and so that there is tension on the cables. Bring hands together in front of you. Try to make your hands overlap (so that the cables cross) a few inches.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/323/view/'),
  ('f8e20a50-000d-4b1a-8ca9-5bf1ac406c8f', 'Cable Cupping', null, 'Attach a single handle to a low cable. Rest your forearm on a bench or your thigh with the palm facing up and the cable pulling your hand away from you. Curl your fingers and wrist toward you as if cupping a ball, squeeze for a second, then lower slowly. This builds the wrist flexion used to control an opponent''s hand in arm wrestling.', null, 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2733/view/'),
  ('479ef6f0-5274-4da7-b5ad-67528ff3c8fd', 'Cable Curls', 'Biceps', 'Bicep Curls using cables. Can be seated or standing', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Brigade7938', 'https://wger.de/en/exercise/1531/view/'),
  ('dc3a2072-abc3-4ef9-b8e6-f5ae6b11bc7f', 'Cable External Rotation', 'Shoulders', 'Steps:
- Start off placing an extension band around a post or in a secure position where it will not release and is at elbow level.
- Position yourself to the side of the band and with your hand that is opposite of the band, reach out and grab the handle.
- Bring the band to your chest keeping your elbow bent in a 90 degree angle then slowly rotate your arm in a backhand motion so that the band externally rotates out
- Continue out as far as possible so that you feel a stretch in your shoulders, hold for a count and then return back to the starting position.
- Repeat for as many reps and sets as desired.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'lauroernesto', 'https://wger.de/en/exercise/142/view/'),
  ('ae695660-7cee-4601-8241-edd3e2a6d896', 'Cable Fly Lower Chest', 'Chest', 'Execution
-
Start position:
- Arms extended out to your sides in a “Y” shape.
- Feel a stretch in your chest (slight bend in elbows — don’t lock them).
-
Movement:
- Bring your hands downward and together in front of your lower chest or upper abs, in a smooth arc motion.
- Squeeze your chest hard at the bottom for 1–2 seconds.
-
Return:
- Slowly raise your arms back up along the same path until you feel a good stretch in your chest.
- Maintain control — don’t let the weights pull you back too quickly.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1691/view/'),
  ('5b4fb3ec-53a1-4525-a58a-c070798ea86e', 'Cable Fly Middle Chest', 'Chest', 'Execution
-
Start position: Arms extended out to your sides (a big “T” shape), feeling a stretch in your chest.
-
Movement: Bring your hands together in front of your chest in a wide hugging motion.
- Focus on squeezing your chest at the center.
- Do not lock your elbows or turn it into a press.
-
Return: Slowly open your arms back to the start, maintaining tension on the chest.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1689/view/'),
  ('b16a28c4-40bf-42d4-94b3-bf3f56fab743', 'Cable Fly Upper Chest', 'Chest', 'Execution
-
Start position:
- Arms down and slightly behind your body, elbows slightly bent.
- Feel a light stretch across your chest.
-
Movement:
- Bring your hands upward and together in front of your upper chest — roughly at chin to collarbone level.
- Use a smooth, controlled motion (avoid jerking).
- Squeeze your chest at the top for 1–2 seconds.
-
Return:
- Slowly let your arms move back down and out to the sides, keeping control and tension.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1690/view/'),
  ('6e03ecb3-6bfe-4b34-be9d-e5c33e820cc6', 'Cable Front Raise with a small bar', 'Shoulders', 'The Cable Front Raise with a small bar isolates your anterior deltoids (front shoulders) by providing constant tension, requiring you to stand facing away from a low pulley, grab the bar with an overhand grip, and lift it in front of you to shoulder height with slightly bent arms, avoiding swinging and keeping your core tight for controlled movement up and down. Use a light-to-moderate weight, focusing on slow, controlled reps to feel the muscle work, not momentum.
How to Perform the Cable Front Raise (Bar)
Setup: Attach a small straight bar to a low cable pulley. Set the weight to a light or moderate setting.
Starting Position: Stand with your back to the machine, holding the bar with an overhand grip (palms facing down) at hip level, arms extended but not locked. Feet shoulder-width apart, core braced, shoulders back and down.
The Lift: Exhale and slowly raise the bar straight up in front of you, keeping a slight bend in your elbows, until your hands reach shoulder height (or slightly below).
The Hold: Pause briefly at the top, squeezing your front delts.
The Lower: Inhale as you slowly and controllably lower the bar back to the starting position, maintaining tension.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1745/view/'),
  ('19a9f67b-60f5-4367-9134-b805f3e73956', 'Cable glute extension', 'Glutes', 'This exercise lets you work the upper, or larger, part of the glutes. For that reason, it should never be missing from your routine of isolated exercises for training the glutes.
Stand in front of a cable machine and locate the low pulley. Then attach the ankle strap to work on the low pulley. As for your posture, you should stay upright at all times. Pay special attention to your back to keep it straight and avoid injury.
It is advisable to hold on to the machine for better balance. With the leg that is holding the weight of the cable, perform a slow stretch backward without bending the knee.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1131/view/'),
  ('81942f3d-d92c-431c-b9d0-0da12918d1e4', 'Cable Lateral Raises (Single Arm)', 'Shoulders', 'The single arm cable lateral raise is a variation of the lateral raise and an exercise used to build the muscles of the shoulders.
- Position a cable at the lowest position possible and attach a single handle.
- Reach across your body and grab the handle with a neutral grip.
- Keep the elbow slightly bent and pull the handle across your body and raise laterally.
- Slowly lower the handle back to the starting position under control.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1378/view/'),
  ('70479b75-0df4-4ac2-a324-4a44b148304c', 'Cable Press Around', 'Shoulders, Chest, Triceps', 'Set the cable pulley at chest height and attach a D-handle bar. Grab
the handle with a neutral grip and hold it next to your chest with your
elbow fully flexed and tight to your side. Turn away from the pulley so
your torso is at 45 degrees.
Hold the other side of the functional trainer with your corresponding hand. Assume a staggered stance for better balance.
While keeping your chest proud, extend your elbow at 45 degrees
across your midline while keeping your arm parallel to the floor. Stop
shy of lockout and contract your chest at the top of the range of motion
(ROM).', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1457/view/'),
  ('821e289e-bd39-4410-b436-6f2a43bc3649', 'Cable pull through', 'Glutes', 'The Cable Pull Through is a lower-body exercise that targets the glutes and hamstrings using a "hip hinge" motion. To perform it, attach a rope to the lowest pulley setting, face away from the machine with the rope between your legs, and step forward to create tension. Keeping your back flat and knees slightly soft, push your hips backward as if trying to close a door behind you until you feel a deep stretch in your hamstrings.
To finish the rep, explosively drive your hips forward to return to a standing position, squeezing your glutes hard at the top. It is vital to remember that this is not a squat; your knees should not bend deeply, and your arms should remain straight and relaxed, acting only as hooks for the rope. This movement provides constant tension on the glutes while placing less stress on the lower back than a traditional deadlift.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'manuher89', 'https://wger.de/en/exercise/1751/view/'),
  ('5d244235-cd56-472a-876e-6e530a899ef2', 'Cable Rear Delt Fly', 'Shoulders, Trapezius', 'The reverse cable fly, also known as the cable rear delt fly, is a deltoid muscle strengthening and definition exercise. It’s one of the best isolation exercises for your back and posterior deltoid.This workout targets your posterior (back) deltoids while using a range of upper body muscles.
- Adjust the weight and the pulleys to the right height. You should be able to see the pulleys because they should be above your head.
- With your right hand, grab the left pulley, and with your left hand, grab the right pulley, crossing them in front of you. This is where you’ll begin your journey.
- Start the movement by moving your arms back and forth while keeping your arms straight.
- Pause at the finish of the move for a brief moment before returning the handles to their starting positions.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/822/view/'),
  ('0285f198-36d5-4a77-bb76-5f72e1a4d6c9', 'Cable Rear-Delt Fly (single arm)', null, 'Cable rear delt fly (single arm):
Stand sideways to a cable machine with the handle set around shoulder height. With a slight bend in the elbow, pull the handle out and back in a wide arc so the upper arm moves away from the body. Keep your torso still and focus on the rear delt doing the work. Use light to moderate weight and controlled reps.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Dulive', 'https://wger.de/en/exercise/1936/view/'),
  ('05853a58-4426-450c-9b06-bfa461a767bf', 'Cable Shrug-In', 'Trapezius', 'Attach a D-handle to each of two low pulleys, stand between them and shrug your shoulders up and inwards, using your upper traps.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1472/view/'),
  ('50889f93-0b3f-4bce-9ec5-fdb4928f9fcc', 'Cable Side Pressure', 'Chest', 'Set a cable at chest height and stand side on with the cable on your working side. Hold the handle with your elbow bent about ninety degrees and close to your body. Press the handle across your body toward your opposite side using your chest and shoulder, then return slowly. This trains the side pressure used to pin an opponent in arm wrestling.', null, 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2735/view/'),
  ('07ded945-de5d-4e77-b13c-17d51a2f0007', 'Cable Tri Extension - Internal Rotation', 'Triceps', 'single arm exercise with cable held at opposite shoulder with elbow bent. Turn towards the cable, and the straighten the elbow across the body.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1662/view/'),
  ('1ea73578-08a5-4f3e-9255-3c58b29b170d', 'Cable Tricep Kickback', 'Triceps', 'Grab onto the handle, and pull your elbow up and back slightly above
your torso. Keep your upper arm to be parallel to the ground for the
duration of the set', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1509/view/'),
  ('5aee8ae1-2752-4868-af62-e3c79954d811', 'Cable Triceps Press', 'Triceps', 'A single arm exercise that starts with the hand close to the chest with with the elbows bent, and the elbow flared out. Press forward and down against the cable straightening the elbow.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1661/view/'),
  ('c867836d-2929-4977-b23c-014bc21ec08d', 'Cable Woodchoppers', 'Obliquus externus abdominis', 'Set cable pulley slightly lower than chest height. Keep body facing forward with hips stable.  Grab the pulley handle, fully extend your arms and bring your arms forward and across your body. Hold for 1 second at the end of the movement and slowly return to starting position.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'robhoyt', 'https://wger.de/en/exercise/145/view/'),
  ('0b342890-4334-4b4f-8013-bd22f5d0d04a', 'Cable Wrist Pronation', null, 'Attach a strap or handle to a cable at hand height so the cable pulls your palm toward facing up. Keep your elbow bent at your side and still. Rotate your forearm so the palm turns down against the cable, then let it rotate back slowly. This builds pronation strength for rolling an opponent''s hand in arm wrestling.', null, 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2736/view/'),
  ('af9f2418-46c2-4c4b-b62e-9d88b99a3c5b', 'Cable Wrist Supination', 'Biceps', 'Attach a strap or handle to a cable at hand height so the cable pulls your palm toward facing down. Keep your elbow bent at your side and still. Rotate your forearm so the palm turns up against the cable, then let it rotate back slowly. This balances pronation work and protects the elbow.', null, 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2737/view/'),
  ('0d79f259-3b28-4258-8a08-cffec062a710', 'Calf Press Using Leg Press Machine', 'Calves, Soleus', 'Put  the balls of your feet on an extended leg press pad.  Use your calves to press the weight by flexing your feet/toes into a pointed position, and releasing back into a relaxed position.
This exercise builds mass and strength in the Gastrocnemius and Soleus muscles as well, if not better, than any calf exercise.', null, 'wger', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/146/view/'),
  ('efeccb1b-73c0-4303-8542-bb4f45ef831a', 'Calf Raise using Hack Squat Machine', 'Calves, Soleus', 'Ideally using a trapeze addon, Lift the weight up using your calves by getting on your toes.', null, 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1466/view/'),
  ('95a9cc46-270e-45f2-8a17-5665a23ff70b', 'Calf Raises on Hackenschmitt Machine', 'Calves', 'Place yourself on the machine with your back firmly against the backrest, the feet are on the platform for calf raises. Check that the feet are half free and that you can completely stretch the calf muscles down.
With straight knees pull up your weight as much as you can. Go with a fluid movement down till the calves are completely stretched. Repeat.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/148/view/'),
  ('db4eaf0f-f4d4-4e63-b9fb-258985bc2858', 'Calf raises, left leg', 'Calves', '- Stand on the floor or on the edge of a step to increase the range of movement.
- Raise one foot.
- Lift your heel until you''re standing on your toes.
- (variable) Stay in this position for three seconds
- Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'wakanda90', 'https://wger.de/en/exercise/1203/view/'),
  ('4e752292-051a-4043-8f80-a390c23875e6', 'Calf raises, one legged', 'Calves', null, null, 'wger', 'CC-BY-SA 4', 'McMarcel13', 'https://wger.de/en/exercise/702/view/'),
  ('04ba9a37-4725-43f0-a0b6-767cdab9a79e', 'Calf raises, right leg', 'Calves', '- Stand on the floor or on the edge of a step to increase the range of movement.
- Raise one foot.
- Lift your heel until you''re standing on your toes.
- (variable) Stay in this position for three seconds
- Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1021/view/'),
  ('05b36227-a331-45b8-b1d5-5c7293c2df17', 'Calves foam roller', 'Calves', 'Move your calves slowly over the foam roller', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1854/view/'),
  ('60ecc95f-2179-46e0-8875-d05f70da6ff0', 'Captain''s Chair Knee Raise', 'Abs', 'Starting position
Step into the captain''s chair (vertical knee raise station). Rest your forearms on the pads and hold the handles. Keep your upper body upright, look straight ahead and press your back against the pad, without rounding or arching it. Your legs are almost straight with a slight bend in the knees, your feet are off the floor and your legs are together.
Movement
Pull your bent legs up, bringing your knees towards your chest. Only go as high as you can while keeping good form, with your legs together the whole time. Then lower your legs again while inhaling, without putting your feet back on the floor.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'fen', 'https://wger.de/en/exercise/2674/view/'),
  ('92d0533f-3deb-40e6-89d2-7563dd6b9c38', 'Captain''s Chair Oblique Knee Raise', 'Obliquus externus abdominis', 'Starting position
Step into the captain''s chair (dip station). Rest your forearms on the pads and grip the handles firmly. Keep your back upright and close to the pad and look straight ahead. Bend your legs so that your thighs and shins form roughly a right angle.
Movement
Raise your knees while turning your legs slightly to one side, about 30-45 degrees, keeping your thighs parallel to the floor. Then do the same to the other side. You can pause briefly in the middle or go straight to the other side.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'fen', 'https://wger.de/en/exercise/2675/view/'),
  ('b02825ca-bbe4-4a07-a162-2b7a6c0a662b', 'Cat Plank', 'Quads, Abs', 'On your fours and raise the knees of the floor ever so slightly.
Curl your back out and push back from your shoulders as to resemble a cat making itself look large.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1911/view/'),
  ('5c4065d5-5e0a-4155-92e5-34a080587a64', 'Cat-Cow', null, 'On all fours. Arch spine up (cat) then drop it down (cow). Breathe with movement.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1938/view/'),
  ('aa22b0b7-795d-47a6-8c0b-fdd0f6b9c8fc', 'Chair dips', 'Triceps', 'Starting position:
Sit down on the front edge of a chair, back straight, hands holding the front edge. Still holding the edge of the chair, arms extended, lift your butt and walk forward slightly so that it is a few inches from the chair.
Steps:
-
Slowly lower your body, keeping the back straight, until your arms are at a right angle.
-
Raise your body again to the initial position, arms extended.
-
Repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1774/view/'),
  ('5c414175-fe72-455a-ba8f-a0575cf792bd', 'Chest Press', 'Chest', '- Adjust the seat height so that the grips are parallel to your chest.
- Use your legs to push the foot forward pedal.
- Bring the handles to the start position.
- Keep your back in contact with the back pad, press outwards.
- Press the handles away from your chest and exhale.
- Allow the handles to come in gently until they reach your chest.
- Allow the handles to return to your chest as you inhale.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/129/view/'),
  ('25cbc266-aa84-44f5-989b-53c9cc8fdc77', 'Chest-Supported Rear Delt Raise', 'Shoulders', '"The Y"
- Position: Set an incline bench to 30-45 degrees. Lie face-down with your chest supported, keeping your head neutral or looking slightly down to avoid neck strain.
- Grip: Hold light dumbbells with a neutral or thumbs-up grip (thumb pointing to the ceiling).
- Movement: With straight or slightly bent elbows, raise the dumbbells up and out in a "Y" shape. Focus on moving the shoulders and shoulder blades rather than just lifting the arms.
- Top Position: Squeeze the shoulder blades together and reach high, ensuring the arms are angled to form a "Y".
- Control: Lower the dumbbells slowly to the starting position.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1825/view/'),
  ('6e1af72c-f9f5-490d-8977-564df4f24b6f', 'Child''s pose', null, 'Starting position:
Start on all fours, knees, toes, and hands touching the ground. Your two big toes should be touching.
Steps:
- Move your knees so that they''re about hip-width apart.
- On an exhale, move your pelvis back to sit on your heels. Your hands should still be touching the ground.
- Relax your upper body, lowering your forehead to the floor and letting your hands move forward naturally.
- Stay in this pose.
Tips:
- To leave the pose, walk your arms back under your shoulders and move your upper body up into a seated position.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1002/view/'),
  ('04e7fd92-e2e5-4212-ad7c-7542e98f7d83', 'Chin tuck', null, 'Starting position:
Sit or stand with your back straight.
Steps:
- Use fingers on your chin to slowly tuck your chin in, moving your head back to align it with your spine.
- Hold for 5 seconds.
- Go back to normal head position and repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1006/view/'),
  ('87e6abc5-a701-442a-b4fb-bb2a7598a754', 'Chin Up', 'Biceps, Lats', 'The chin-up (also known as a chin or chinup) is a strength training exercise. People frequently do this exercise with the intention of strengthening muscles such as the latissimus dorsi and biceps, which extend the shoulder and flex the elbow, respectively. In this maneuver, the palms are faced towards the body. It is a form of pull-up in which the range of motion is established in relation to a person''s chin.', 'Pull-up bar', 'wger', 'CC0', 'BFad07', 'https://wger.de/en/exercise/152/view/'),
  ('5fd01c23-6c54-40cb-9a67-87c7a325baee', 'Chin-up Isometric Hold', 'Lats', 'Grip the bar with an underhand grip (palms facing you) and pull yourself up until your chin is at or above the bar.
Hold this top position for the set time, keeping your core tight, your shoulders stable and your body still.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1282/view/'),
  ('ca3ca5d0-5231-4420-ad06-fa3d32693a1b', 'Clamshell', 'Glutes, Abs', 'Position
Side plank with the elbow and the forearm on the ground and the legs slightly bent.
Execution
Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1823/view/'),
  ('f77b7cc6-e163-4f92-afa8-5ec431f32588', 'Clamshell to Reverse Clamshell', 'Glutes', 'Lie on your side with your hips and knees bent, keeping your legs stacked. Lift your top knee into a clamshell position and keep the leg elevated throughout the movement. From there, alternate between opening the knee upward and lifting the foot upward, moving through hip external and internal rotation.
Keep the movement slow and controlled. Do not let the top leg rest on the bottom leg between repetitions.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'TobiasFalk', 'https://wger.de/en/exercise/2449/view/'),
  ('fdeb0973-121f-494d-8b94-54f1d7ba003f', 'Clap Push-UP', 'Chest', 'The clap push-up is an explosive upper body movement that builds power and fast-twitch muscle strength. It adds a plyometric challenge to the traditional push-up by requiring the hands to leave the ground mid-rep.
- Start in a strong push-up position with your hands slightly wider than shoulder-width and core engaged
- Lower your body explosively and push off the ground with enough force to lift your hands.
- Quickly clap your hands together at chest level before returning them to the floor.
- Land with soft elbows to absorb the impact and immediately move into the next rep', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1554/view/'),
  ('ecf9c0e2-a1d0-4e6e-90e9-5c029e98f2c9', 'Claps over the head', 'Shoulders', 'Stand with your feet shoulder width apart. Raise your arms and clap over your head', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1223/view/'),
  ('a8f76beb-b6d8-430b-8e45-cc03d4959043', 'Clean', 'Glutes, Quads', 'Regular olympic lift clean.
Pull bar from ground, catch on shoulders performing a front squat.', 'Barbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1438/view/'),
  ('8c509754-c86f-4c1b-bfa9-29c906ffc409', 'Clean and Jerk OL', 'Shoulders, Hamstrings, Glutes, Quads', 'Olympic lift clean and jerk.
Combination of clean and jerk in one motion.', 'Barbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1446/view/'),
  ('2a125f64-1d10-4926-95ad-33a48e61b3d6', 'Clean and Press', 'Shoulders', '- The First Pull: Lift the bar from the floor to knee-height by driving with the legs, keeping the angle of your back constant.
- The "Power" Position: As the bar reaches mid-thigh, explosively shrug and extend your hips to create vertical momentum.
- The Quick Elbow Turnover: In the catch phase, rotate your elbows rapidly under the bar to create a "shelf" on your front deltoids.
- The Vertical Press: Press the bar in a straight line; your head should shift slightly forward once the bar clears your forehead to reach full lockout.', 'Barbell', 'wger', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1901/view/'),
  ('2536b8cd-a287-48ee-b8da-58d8bd595f43', 'ClimbMill', 'Quads', 'The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance.', null, 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1449/view/'),
  ('b50a3d3e-cf75-42de-8729-80e163748fb1', 'Clockwise neck circles', null, 'Starting position:
Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.
Steps:
In a slower fluid motion and with your head relaxed and not pushing in any direction:
- lean toward your right shoulder.
- then bring your head back, facing up.
- then lean toward your left shoulder.4.and back toward the starting position.
Keep repeating this as part of one slower fluid motion.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1015/view/'),
  ('63fbb8e5-6ebc-4def-8844-3e65e097213b', 'Close-grip Lat Pull Down', 'Lats', 'Grip the pull-down bar with your hands closer than shoulder width apart, with your palms facing away from you. Lean back slightly. Pull the bar down towards your chest, keeping your elbows close to your sides as you come down. Pull your shoulders back at the end of the motion.', null, 'wger', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/158/view/'),
  ('44cfa56c-d8c2-4f2c-8b5a-f29810fd60e7', 'Close-grip Press-ups', 'Brachialis, Lats, Chest, Trapezius', 'Drop into a strong plank position, bringing your hands close together until they''re almost touching. (picture 1)Bend your elbows to slowly bring your chest to the floor (picture 2). Keep your elbows close to your body as you push back up explosively. Repeat. Ensure you take your time lowering on each rep, keeping your form sharp.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1086/view/'),
  ('4eb41bfb-cbeb-4683-b9c6-902ee7e028e0', 'Close-grip supinated lat pulldown', 'Lats', 'Downward movement:
- Pull the bar down so that it passes close to your chin and touches the upper part of your chest.
- Keep the rest of your body still.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1127/view/'),
  ('d8d1b919-94e1-4e91-b37e-29bb8a479740', 'Cobra Stretch', 'Abs', 'The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1450/view/'),
  ('e872658a-3bac-4d9e-bcf2-15919ebea43a', 'commando pull-ups', 'Shoulders, Biceps, Lats, Trapezius', 'variation of the pull-up exercise, it is performed with a grip of one hand supine and one hand prone, do not twist the torso to get back to the front, the head passes once to one side, once to the other.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/980/view/'),
  ('a7cdf860-b91c-46ac-87f6-c2cd9fde8ac5', 'Controlled Brisk Swim', 'Shoulders, Lats', 'Swim a short pool length at a controlled brisk effort, maintaining smooth strokes and steady breathing. Stop at the wall for the prescribed recovery before the next repeat. This is a submaximal swim interval, not an all-out sprint; distance, repeats and rest are set by the routine.', null, 'wger', 'CC-BY-SA 4', 'Original exercise instructions prepared for nalhilal', 'https://wger.de/en/exercise/2695/view/'),
  ('1544c78d-fe6d-423d-876e-0ba1998063c6', 'Cool-Down Swim', 'Shoulders, Lats, Chest', 'Swim at an easy, unhurried pace — freestyle, backstroke, or just floating/gliding — with zero focus on technique or drills. The only goal here is to let your heart rate come down gradually and your muscles relax before you get out of the pool.', null, 'wger', 'CC-BY-SA 4', 'Imported from swim plan', 'https://wger.de/en/exercise/2487/view/'),
  ('dbed4613-e1d5-483f-90ae-6db5d593911e', 'Copenhagen Adduction Exercise', 'Glutes, Quads', 'Lie on your side with the elbow placed directly under the shoulder, similar to a side plank position. Place the upper leg on a bench with the inside of the foot or ankle resting on it. Lift your hips and hold your body in a straight line while keeping the lower leg off the floor. The exercise strongly activates the adductors of the upper leg while also challenging the core and hip stabilizers.', 'Bench', 'wger', 'CC-BY-SA 4', 'RiccaBaro', 'https://wger.de/en/exercise/1605/view/'),
  ('1b140999-e1fa-49b5-9f2b-690bac959db3', 'Core Rotation', 'Quads, Abs', 'Sit back, raise feet above the ground with knees bent and start rotating left and right with hands touching the ground every move.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1912/view/'),
  ('96a899ee-16a4-457d-8f66-efdd39fd38a0', 'Cossack squat', 'Glutes, Quads', 'The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way.', null, 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1407/view/'),
  ('26168c76-5e2a-4321-8755-5ca42bd341ad', 'Couch Stretch', null, '- Stand facing away from a bench, couch or similar-height object.
- Extend one leg backwards, resting your foot "laces-down" on the edge of the bench.
- Lower yourself until your rear knee is on the floor and you are in a lunge position, with your torso hanging forwards slightly.
- Brace your core, tense your rear glute, and straighten up your torso to vertical, under control. Relax and repeat.
Repeat for the other leg, too.', 'Bench', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2525/view/'),
  ('00ecb956-9483-4d08-a9b1-6a236d4d8ff3', 'Counterclockwise neck circles', null, 'Starting position:
Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.
Steps:
In a slower fluid motion and with your head relaxed and not pushing in any direction:
- lean toward your left shoulder.
- then bring your head back, facing up.
- then lean toward your right shoulder.4.and back toward the starting position.
Keep repeating this as part of one slower fluid motion.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1016/view/'),
  ('6e00afb6-272d-44a2-8ae3-e7fa41b50f06', 'Cross-Bench Dumbbell Pullovers', 'Lats, Chest, Serratus anterior', 'Grasp a moderately weighted dumbbell so your palms are flat against the underside of the top plates and your thumbs are around the bar. Lie on your back across a flat bench so only your upper back and shoulders are in contact with the bench. Your feet should be set about shoulder-width apart and your head should hang slightly downward. With the dumbbell supported at arm''s length directly about your chest, bend your arms about 15 degrees and keep them bent throughout the movement. Slowly lower the dumbbell backward and downward in a semicircle arc to as low a position as is comfortably possible. Raise it slowly back along the same arc to the starting point, and repeat for the required number of repetitions.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'powerade69', 'https://wger.de/en/exercise/161/view/'),
  ('37314b67-1aad-4405-aa88-70846d5f035d', 'Cross-Body Cable Y-Raise', 'Shoulders, Lats, Trapezius', 'Attach a D-Bar to the cable machine. Perform a motion akin to drawing a sword from across your body.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1458/view/'),
  ('570a55a7-bb5e-4ae4-8503-e434acbb5e86', 'Cross-Body Stretch', 'Shoulders', 'Extend your right arm straight across your chest toward the left. Hook your left arm around your right elbow and pull your right arm a little closer to your body. Keep your shoulder down as you do this. Repeat on the other side.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'tobias08', 'https://wger.de/en/exercise/2685/view/'),
  ('4f38cc2e-5904-4ef5-b811-e729105cfd3b', 'Crossbody Hamstring Stretch', 'Hamstrings', 'While standing, cross one leg behind the other (keep this leg straight). Reach downward and try to touch the toes of that leg. Slightly bend the other leg so that you can bend down.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1400/view/'),
  ('bb948d34-8948-4995-9e59-003d7b6fc1b2', 'Crossbody Leg Swings', 'Hamstrings', 'Hold onto a wall or something near you for support. Swing one leg across the front of your body, then back and out to the side. Repeat while slowly increasing your range of motion.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1395/view/'),
  ('b186f1f8-4957-44dc-bf30-d0b00064ce6f', 'Crunches', 'Abs', 'Lay down on your back a soft surface, the feet are on the floor. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.', 'Gym mat', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/167/view/'),
  ('e0af7f44-bda9-4829-9ed6-a2d60d443b14', 'Crunches (Custom)', 'Abs', 'Perform Crunches with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'Gym mat', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2704/view/'),
  ('401989e0-64c3-459d-bc47-2c171ab4f41d', 'Crunches on Machine', 'Abs', 'The procedure is very similar as for regular crunches, only with the additional weight of the machine. Sit on the machine, put both feet firmly on the ground. Grab the to the weights, cables, etc. and do a rolling motion forwards (the spine should ideally lose touch vertebra by vertebra). Slowly return to the starting position.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/172/view/'),
  ('29175281-afaf-4ffd-85e8-cfc38493e304', 'Crunches With Cable', 'Abs', 'Take the cable on your hands and hold it next to your temples. Knee down and hold your upper body straight and bend forward. Go down with a fast movement, rolling your back in (your ellbows point to your knees). Once down, go slowly back to the initial position.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/173/view/'),
  ('35543ba9-46a6-4ad2-b05a-8062734e6a83', 'Crunches With Cable (Custom)', 'Abs', 'Perform Crunches With Cable with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2705/view/'),
  ('b7ff64bc-7a7c-4dbc-af6f-fabc20425f5f', 'Crunches With Legs Up', 'Abs', 'On your back, legs extended straight up, reach toward your toes with your hands and lift your shoulder blades off the ground and back.', null, 'wger', 'CC-BY-SA 4', 'krisbbb', 'https://wger.de/en/exercise/174/view/'),
  ('9828f705-350b-4afd-86c4-fcc0e8a0fb4b', 'Curl - With Shoulder Elevated', 'Biceps', 'Place elbow so that it is about level with the shoulder. Curl the wieght to your shoulder. Focus on the stretch in the eccentric part of the curl', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1666/view/'),
  ('4b67ccf1-6bbc-406a-b88b-e2f72b10085e', 'Curl De Muñeca Con Barra', null, 'This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso.
-
Starting Position: Grip a bar with an overhand grip (palms facing up) at a width similar to your shoulders.
-
Position on the Bench: Kneel in front of a flat bench and rest the backs of your forearms on it. Your wrists and hands should extend slightly beyond the edge of the bench to allow for a full range of motion.
-
Eccentric Phase (Lowering): Lower the bar in a controlled manner by extending your wrists toward the floor. At the bottom of the movement, slightly spread your fingers to let the bar roll down a bit, maximizing the stretch.
-
Concentric Phase (Lift): First, close your fingers to secure the bar, then flex your wrists upward explosively but in a controlled manner, bringing the bar as high as possible. Strongly contract your forearms at the top position for one second.
-
Form: Keep your forearms firmly pressed against the bench throughout the exercise; only your wrists and fingers should move.', 'Barbell, Bench', 'wger', 'CC-BY-SA 4', 'xWan', 'https://wger.de/en/exercise/2452/view/'),
  ('3de523ee-d359-4044-a792-6de22eef0495', 'Curl with kettlebell two hands', 'Biceps', 'Stand upright and grip the kettlebell with both hands. Perform the elbow flexion motion, starting from a fully extended position until your hand reaches shoulder height. Spread your legs a little for stability and, to perform the exercise correctly, try not to push with your back or body in general. Change the weight of the kettlebell to adjust the difficulty.', 'Kettlebell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/974/view/'),
  ('8dedde58-a5dc-4a23-ad20-fd7cf524f8b5', 'Cycling', 'Obliquus externus abdominis, Trapezius', 'Cycling, also called bicycling or biking, is the use of bicycles for transport, recreation, exercise or sport. People engaged in cycling are referred to as cyclists, bicyclists, or bikers. Apart from two-wheeled bicycles, cycling also includes the riding of unicycles, tricycles, quadracycles, recumbent and similar human-powered vehicles.', 'none (bodyweight exercise)', 'wger', 'CC0', 'BFad07', 'https://wger.de/en/exercise/177/view/'),
  ('517265a2-e4f7-4b33-979f-9be1efd86343', 'Cycling cardio session', null, 'Cardio session on a Technogym Bike Excite 1000 stationary bike.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1204/view/'),
  ('038f7cb1-6aa3-4c48-a19d-a31993f7b0d8', 'DB Cross Body Hammer Curls', 'Biceps', 'Hammer curl with a neutral grip, curling the dumbbell across your body towards the opposite shoulder. Works the brachialis in particular.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1502/view/'),
  ('7b40813b-80a3-42cc-8938-0c5199ef7620', 'DB Underhand bench press', 'Chest', 'Underhand grip DB, perform a normal bench press movement, keeping the elbows close to the chest', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1497/view/'),
  ('4b23738a-67a8-41af-996d-abc53a7c3f97', 'DB Upper Chest Variation', 'Chest', 'Dumbbell in hand in a curl fashion, lean body into the arm to help the dumbbell up above the chest, next to the head, to activate chest and delt combo', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1496/view/'),
  ('73646b21-62e3-493b-8d75-4179326cd404', 'DB Wrist Extension', null, 'Grab two dumbbells with an overhand grip and lay your forearms across your knees.
Let your wrists flex fully, then extend your wrists.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Deflation', 'https://wger.de/en/exercise/1881/view/'),
  ('2a6e3987-5340-4bac-a826-5b7479c765bc', 'Dead Bug (Custom)', 'Abs', 'Lie on your back, press your lower back into the floor, extend opposite arm and leg slowly, keep the spine neutral, breathe steadily, return under control without arching.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2752/view/'),
  ('1374e9ba-27cc-4d9f-81ca-5609083cb25e', 'Dead Bug Breathing (Custom)', 'Abs', 'Lie on your back, breathe in fully, let the ribs sink down, press the lower back into the floor, exhale slowly while keeping intra-abdominal pressure, five reps per set.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2760/view/'),
  ('d4db2355-4c99-4d80-a179-6aeced7c7fed', 'Deadbug', 'Abs', 'Lie on your back, with your hips and knees bent to 90°. Raise both arms toward the ceiling. Pull your lower back to the floor to eliminate the gap. Start by pressing one leg out, and tapping the heel to the floor. "As you extend one leg, exhale as much as you can, keeping your lower back glued to the floor," Dunham says. When you can’t exhale any more, pull your knee back to the starting position. Make this more difficult by holding weight in your hands, or by lowering opposite arm and leg.', null, 'wger', 'CC-BY-SA 4', 'Metin', 'https://wger.de/en/exercise/178/view/'),
  ('74d4697d-8a97-4ea2-9d05-fa4d2bd7221e', 'Deadhang', null, 'Deadhang performed on an edge either with or without added weight (adujst edge or weight to adjust difficulty)', null, 'wger', 'CC-BY-SA 4', '2dPREtEZP221u68Akf0JImv5L48', 'https://wger.de/en/exercise/182/view/'),
  ('ee8e8db4-2d82-49e1-ab7f-891e9a354934', 'Deadlifts', 'Lats', 'Stand firmly, with your feet slightly more than shoulder wide apart. Stand directly behind the bar where it should barely touch your shin, your feet pointing a bit out. Bend down with a straight back, the knees also pointing somewhat out. Grab the bar with a shoulder wide grip, one overhand, one underhand (mixed grip).
Pull the weight up. At the highest point make a slight hollow back and pull the bar back. Hold 1 or 2 seconds that position. Go down, making sure the back is not bent. Once down you can either go back again as soon as the weights touch the floor, or make a pause, depending on the weight.', 'Barbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/184/view/'),
  ('9ac4813e-79a6-4a4d-ab93-9cfa5bf7b8fa', 'Decline Bench Leg Raise', 'Abs', '- Setup: Lie on a decline bench with your head at the top and grip the handles.
- The Start: Extend legs fully, keeping them slightly elevated to engage your core.
- The Lift: Raise your legs toward the ceiling using your abs, not momentum.
- The Squeeze: Pause and contract your lower abdominals at the top.
- The Return: Lower your legs slowly to the starting position with control.', 'Incline bench', 'wger', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1889/view/'),
  ('bcd801f0-9a38-4615-a91c-900153c8c234', 'Decline Bench Press Barbell', 'Chest', 'Lay down on a decline bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.', 'Barbell, Bench', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/185/view/'),
  ('dda69c96-62d4-4690-aa07-a4a0f6ceb63a', 'Decline Bench Press Dumbbell', 'Chest', 'Take two dumbbells and sit on a decline bench, the feet are firmly on the floor, the head is resting the bench. Hold the weights next to the chest, at the height of your nipples and press them up till the arms are stretched. Let the weight slowly and controlled down.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/186/view/'),
  ('fae44c34-2e85-4d22-8fb8-7b14faf14719', 'Deep breathing (standing or seated)', 'Obliquus externus abdominis, Abs', 'A conscious breathing technique to improve oxygenation, reduce stress and connect with the present moment.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1591/view/'),
  ('e7a964cd-e68e-4926-bc7c-577065137e18', 'Deficit Deadlift', null, 'Preparation
Stand on weight plate, bumper plate, or shallow elevated platform with loaded bar above feet. Squat down and grasp bar with shoulder width or slightly wider overhand or mixed grip.
Execution
Lift bar by extending hips and knees to full extension. Pull shoulders back at top of lift if rounded. Return weights to floor by bending hips back while allowing knees to bend forward, keeping back straight and knees pointed same direction as feet. Repeat.
Comments
Throughout lift, keep hips low, shoulders high, arms and back straight. Knees should point same direction as feet throughout movement. Keep bar close to body to improve mechanical leverage. Grip strength and strength endurance often limit ability to perform multiple reps at heavy resistances. Gym chalk, wrist straps, grip work, and mixed grip can be used to enhance grip. Mixed grip indicates one hand holding with overhand grip and other hand holding with underhand grip. Lever barbell jack can be used to lift barbell from floor for easier loading and unloading of weight plates.
Barbell Deficit Deadlift emphasizes building strength through lowest portion of Deadlift. Target muscle is exercised isometrically. Heavy barbell deadlifts significantly engages Latissmus Dorsi. See Barbell Deficit Deadlift under Gluteus Maximus. Also see Deadlift Analysis.', 'Barbell', 'wger', 'CC-BY-SA 4', 'bobbyprince89', 'https://wger.de/en/exercise/189/view/'),
  ('b7dd3766-f660-45dc-bbe1-10e15e2f7cee', 'Deficit Push ups', 'Chest', 'Push-ups with your hands on blocks or push-up handles, so that you can lower your chest below the level of your hands.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1777/view/'),
  ('6a448382-0ea9-4f41-8a83-0b7cd7d8a2bf', 'Delt Stretch', 'Shoulders', 'Stretch your deltoids for a certain period of time.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1536/view/'),
  ('bb9b994e-426f-4693-9d16-3f8d5a9c72b8', 'Devil’s Press', 'Shoulders, Glutes, Chest', 'The Devil’s Press is a hybrid movement combining a dumbbell burpee and a double dumbbell snatch. It’s a full-body, high-intensity exercise that develops strength, power, and metabolic conditioning.
- Start with a dumbbell in each hand and perform a burpee, letting your chest touch the ground while holding the dumbbells.
- Explosively jump your feet forward and swing the dumbbells between your legs.
- Drive the dumbbells overhead in one continuous motion, locking out your arms.
- Lower the dumbbells with control to return to the starting position and repeat', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1556/view/'),
  ('14d5cdbc-9b17-4296-a282-0a81cd3c4c4e', 'Diagonal Shoulder Press', null, 'You sit at the bench press device, back slightly tilted to the back. The bar should be about 20 cm in front of you. Then you push the bar and take it back again, as you would with a bench press.
In this position you strain your chest muscles a lot less, which is nice if you want to train, but your chest hasn''t recovered yet.', 'Bench', 'wger', 'CC-BY-SA 4', 'oboema', 'https://wger.de/en/exercise/193/view/'),
  ('de22963a-5d42-4999-860e-377f64359432', 'Diamond push ups', 'Chest', 'Start: Get into a plank. Place hands close together under your chest so thumbs and index fingers form a diamond shape.
Lower: Bend your elbows to lower your chest toward your hands. Keep your body straight.
Push: Push back up until arms are fully extended.
New note Keep elbows close to your body and core tight.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'notdefine', 'https://wger.de/en/exercise/386/view/'),
  ('4632c471-5c5e-4570-9dec-509c5d4d58bb', 'Diaphragmatic Breathing', null, 'Belly breathing. Hand on chest stays still, hand on belly rises. 8-10 slow breaths.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1940/view/'),
  ('09dd3e3c-e53a-4e2c-a2e3-645d334f53e2', 'Dips', 'Chest, Triceps', 'A dip is an upper-body strength exercise. Narrow, shoulder-width dips primarily train the triceps, with major synergists being the anterior deltoid, the pectoralis muscles (sternal, clavicular, and minor), and the rhomboid muscles of the back (in that order).[1] Wide arm training places additional emphasis on the pectoral muscles, similar in respect to the way a wide grip bench press would focus more on the pectorals and less on the triceps.', 'none (bodyweight exercise)', 'wger', 'CC0', 'BFad07', 'https://wger.de/en/exercise/194/view/'),
  ('6f9073e4-d9f5-4d0a-a0ee-d43324c5e41b', 'Dips (Custom)', 'Chest, Triceps', 'Perform Dips with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2706/view/'),
  ('7c8eb1ac-2d7e-4ca7-919a-1848ba38e0f4', 'Dips Between Two Benches', 'Triceps', 'Put two benches so far appart, that you can hold onto one with your hands and are just able to reach the other with your feet. The legs stay during the exercise completely stretched. With your elbows facing back, bend them as much as you can. Push yourself up, but don''t stretch out the arms.', 'Bench', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/197/view/'),
  ('adbb1d4c-962b-4a26-a353-9c47a2b37a93', 'Doorway Pectoral Stretch', 'Chest', '- Place the forearm vertically on a door frame or stationary object at head height
- Step forward past the arm, keeping it still against the object to stretch the chest', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1713/view/'),
  ('fe249e2f-5856-420f-8a34-1b02c7fde141', 'Double Kettlebell Clean and Press', 'Shoulders, Biceps, Brachialis, Quads, Trapezius, Triceps', 'Full-body muscles building exercise. This exercise provides a huge range of benefits in terms of strength & size and is extremely functional.', 'Kettlebell', 'wger', 'CC-BY-SA 4', 'm4k3r', 'https://wger.de/en/exercise/1360/view/'),
  ('a030a4e9-970c-4442-b0b3-e49b42143de0', 'Double Kettlebell Front Squat', 'Glutes, Quads', 'The kettlebell front squat is a compound, multi-joint exercise that works several muscle groups.', 'Kettlebell', 'wger', 'CC-BY-SA 4', 'm4k3r', 'https://wger.de/en/exercise/1361/view/'),
  ('58ca3e51-ea64-4771-a74a-a74d29f5c40c', 'Double Leg Calf Raise', 'Calves, Soleus', 'The double leg heel raise is important to strengthen and create control and stability around the ankle and knee, and provide balance and control for the hip and pelvis.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1243/view/'),
  ('f0823bb5-3f18-48d4-98de-cbe38f9fd8ff', 'Double-Leg Abdominal Press', 'Abs', 'Lie on your back with knees and hips bent at 90 degrees (tabletop).
Place your hands on your thighs just above your knees. Push your hands against your knees as hard as possible while using your abs to pull your knees toward your hands.
Hold for 10 seconds of maximum effort. Your abs should be shaking.', 'Gym mat', 'wger', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1827/view/'),
  ('02b96dc1-d1d9-4fc7-b54c-82dda1691485', 'Drag Pushdown', 'Triceps', '- Starting
position for this rope pushdown is standing facing a cable machine with
the handles of a rope attachment in both hands and feet shoulder width
apart.
- Hinge
forward slightly at the hips maintaining an upright chest and bring the
shoulders and elbows behind the body so that when you push down on the
cable attachments, you can get a fully contracted triceps long head.
- Drag
the cable machine rope attachment as close to the body as possible and
straighten your elbows until lockout.', 'Cable machine, SZ-Bar', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1481/view/'),
  ('8c132ea0-7885-474f-8514-0909ae22bdf6', 'Dragon squat', 'Quads', 'Start standing with your feet hip-width apart. Cross your right foot behind you to the left corner and back of the room while bending both knees. Return and repeat, alternating sides. Keep your hips and shoulders forward as you cross your feet and bend your knees.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1201/view/'),
  ('f5ad82a8-adf8-4795-9874-1f6d183c56ed', 'Dragon-flag', 'Obliquus externus abdominis, Abs', 'Keep your body completely rigid throughout the movement, avoiding sagging in your lower back.
Use a firm grip to stabilize your upper body.
Start with simpler versions (such as with bent knees) to build strength and control.', null, 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1409/view/'),
  ('15ee508d-fbd7-4acf-ab44-e35525582693', 'Drop Curl', 'Biceps', 'Drop curls in a modified position at a slow pace effectively engage the brachialis for arm width.
Starting position is with both arms in a slight angle towards each other at chest height with a dumbbell in each hand. Lower one dumbbell close to full extended arm position slowly and in a controlled manner during the first half of the curl, then curl it back up to starting position, while the other dumbbell stays at its starting position. Now lower the other dumbbell down. This keeps tension on the brachialis. As we pass the 90deg mark on our way down, the biceps will take over the work.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1512/view/'),
  ('51ab6376-eb3e-42dc-ad48-46166c94adac', 'Dumbbell Bent Over Face Pull', 'Shoulders, Lats', 'This exercise involves using dumbbells to perform a bent over face pull, which targets the upper back and shoulders. The movement involves pulling the weights towards the face while keeping the elbows high and squeezing the shoulder blades together.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1639/view/'),
  ('8675ea3b-0e8b-4a08-9e82-4525ec91dd23', 'Dumbbell bicep curl to press', 'Biceps', 'Bend your elbows and lift the dumbbells to your shoulders.
Push the dumbbells over your head while rotating your arms to make your palms face forward. Reverse it to lower down. Repeat the exercise.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1226/view/'),
  ('82f19d1c-f12b-49f0-bfdd-24239f93eabc', 'Dumbbell Bradford press', 'Shoulders', 'From a front hold of the DBs in a OHP, press above the head, bring back towards the rear of the shoulders, down, and press back forward.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1504/view/')
on conflict do nothing;

