  ('203a6fee-7436-4313-858f-c1e364136793'::uuid, 'image', 'wger/203a6fee-7436-4313-858f-c1e364136793/662db55d-68d0-4297-8215-3dcf6c21c778.jpg', 'CC-BY-SA 4', null, null, false, 1),
